    #[test]
    fn ext_generic_impl_away_from_template_file_e0387() {
        // Concrete-only in v1: a generic impl must stay in the file that
        // declares its template, even inside the same package.
        let diags = check_multifile_src(
            "acme.src.b",
            &[
                ("acme.src.a", "struct Holder[T] { v: T }\n"),
                (
                    "acme.src.b",
                    "impl Holder[T] { fn get(this) -> T { return this.v; } }\n\
                     fn main() -> i32 { return 0; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(
            codes.contains(&"E0387"),
            "a generic impl away from its template file is E0387; got {codes:?}"
        );
    }

    #[test]
    fn ext_underscore_field_from_extension_file_e0403() {
        // The `_` privacy rule reads the same across files INSIDE a package:
        // an extension block is another file, so `_` fields stay off-limits —
        // exactly the restriction the maui-regen plan promises for generated
        // contract files.
        let diags = check_multifile_src(
            "acme.src.ext",
            &[
                (
                    "acme.src.geom",
                    "struct Point { _x: i32 }\n\
                     impl Point { fn new() -> Point { return Point { _x: 5 }; } }\n",
                ),
                (
                    "acme.src.ext",
                    "impl Point { fn peek(this) -> i32 { return this._x; } }\n\
                     fn main() -> i32 { return 0; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(
            codes.contains(&"E0403"),
            "an extension file reading a `_` field is E0403; got {codes:?}"
        );
    }

    #[test]
    fn ext_duplicate_method_across_files_e0326() {
        let diags = check_multifile_src(
            "acme.src.main",
            &[
                (
                    "acme.src.geom",
                    "struct Point { x: i32 }\n\
                     impl Point { fn sum(this) -> i32 { return this.x; } }\n",
                ),
                (
                    "acme.src.ext",
                    "impl Point { fn sum(this) -> i32 { return 0; } }\n",
                ),
                ("acme.src.main", "fn main() -> i32 { return 0; }\n"),
            ],
        );
        let codes = error_codes(diags);
        assert!(
            codes.contains(&"E0326"),
            "the same method declared in two files of the package is a duplicate; got {codes:?}"
        );
    }

    #[test]
    fn raw_ptr_struct_nonunderscore_field_is_public_cross_file() {
        // v0.0.24 #10: the language does NOT infer privacy from a struct's
        // raw-pointer/`drop` shape. A raw-ptr field that is not `_`-prefixed is
        // public; reading it cross-file is clean.
        let diags = check_multifile_src(
            "main",
            &[
                (
                    "handles",
                    "struct Handle { opaque ptr: *u8, len: usize }\n\
                     impl Handle { fn new() -> Handle { return Handle { ptr: { 0 as *u8 }, len: 4 as usize }; } }\n",
                ),
                (
                    "main",
                    "fn main() -> i32 { let h: Handle = Handle::new(); let n: usize = h.len; return n as i32; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(
            !codes.contains(&"E0403"),
            "non-`_` field on a raw-ptr struct is public now; expected no E0403, got {codes:?}"
        );
    }

    #[test]
    fn underscore_field_read_cross_file_is_private_e0403() {
        // The `_` prefix is the only field-privacy mechanism. A `_`-named field
        // is module-private even on a raw-ptr struct; reading it cross-file is
        // E0403.
        let diags = check_multifile_src(
            "main",
            &[
                (
                    "handles",
                    "struct Handle { opaque ptr: *u8, _len: usize }\n\
                     impl Handle { fn new() -> Handle { return Handle { ptr: { 0 as *u8 }, _len: 4 as usize }; } }\n",
                ),
                (
                    "main",
                    "fn main() -> i32 { let h: Handle = Handle::new(); let n: usize = h._len; return n as i32; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(codes.contains(&"E0403"), "expected E0403 on `_len`, got {codes:?}");
    }

    #[test]
    fn underscore_field_literal_cross_file_is_private_e0403() {
        // Naming a `_`-private field in a cross-file struct literal is rejected;
        // the public (`ptr`) field alongside it is fine.
        let diags = check_multifile_src(
            "main",
            &[
                ("handles", "struct Handle { opaque ptr: *u8, _len: usize }\n"),
                (
                    "main",
                    "fn main() -> i32 { let h: Handle = Handle { ptr: { 0 as *u8 }, _len: 4 as usize }; return 0; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(codes.contains(&"E0403"), "expected E0403 on `_len` literal, got {codes:?}");
    }

    #[test]
    fn underscore_field_on_generic_struct_cross_file_is_private_e0403() {
        // v0.0.24 #10: name-based privacy must fire on GENERIC instantiations
        // too. A lazily-synthesized `Box[i32]` inherits its template's origin
        // file, so reading `_p` cross-file is E0403 — the same as a concrete
        // struct. (Regression: instantiations used to be born with no
        // origin_file, so privacy silently never fired for Vec/Box/Arc/...)
        let diags = check_multifile_src(
            "main",
            &[
                (
                    "boxes",
                    "struct Box[T] { _p: T }\n\
                     impl Box[T] { fn of(take v: T) -> Box[T] { return Box[T] { _p: v }; } }\n",
                ),
                (
                    "main",
                    "fn main() -> i32 { let b: Box[i32] = Box[i32]::of(7); return b._p; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(codes.contains(&"E0403"), "expected E0403 on generic `_p`, got {codes:?}");
    }

    #[test]
    fn public_field_on_generic_struct_cross_file_clean() {
        // The non-`_` field of a generic instantiation stays public cross-file.
        let diags = check_multifile_src(
            "main",
            &[
                (
                    "boxes",
                    "struct Box[T] { v: T }\n\
                     impl Box[T] { fn of(take v: T) -> Box[T] { return Box[T] { v: v }; } }\n",
                ),
                (
                    "main",
                    "fn main() -> i32 { let b: Box[i32] = Box[i32]::of(7); return b.v; }\n",
                ),
            ],
        );
        let codes = error_codes(diags);
        assert!(!codes.contains(&"E0403"), "public generic field should be reachable, got {codes:?}");
    }

    #[test]
    fn raw_ptr_struct_fields_same_file_clean() {
        let diags = check_multifile_src(
            "main",
            &[(
                "main",
                "struct Handle { opaque ptr: *u8, len: usize }\n\
                 fn main() -> i32 { let h: Handle = Handle { ptr: { 0 as *u8 }, len: 4 as usize }; let n: usize = h.len; return n as i32; }\n",
            )],
        );
        assert!(
            diags.is_empty(),
            "expected clean type-check, got: {diags:#?}"
        );
    }

    #[test]
    fn raw_ptr_struct_nonunderscore_fields_public_export_and_repr_c() {
        // Non-`_` fields are public on every struct shape — `export`, `#[repr(C)]`,
        // or plain. Cross-file reads of `ptr`/`len` here are clean.
        let diags = check_multifile_src(
            "main",
            &[
                (
                    "handles",
                    "export struct Exported { opaque ptr: *u8, len: usize }\n\
                     #[repr(C)] struct CHandle { opaque ptr: *u8, len: usize }\n",
                ),
                (
                    "main",
                    "fn take_exported(h: Exported) -> i32 { let n: usize = h.len; return n as i32; }\n\
                     fn take_c(h: CHandle) -> i32 { let n: usize = h.len; return n as i32; }\n\
                     fn main() -> i32 { return 0; }\n",
                ),
            ],
        );
        assert!(
            diags.is_empty(),
            "expected clean type-check, got: {diags:#?}"
        );
    }

    // ---- generic-fn-body move / borrow / method checking ----
    //
    // Generic free-fn bodies are now type-/move-/borrow-checked with their
    // type params treated abstractly (unbounded `T` is move-only; `T: Copy`
    // is Copy). Before, generic bodies were skipped entirely, so these bugs
    // reached codegen (a panic, or a silent double-free).

    #[test]
    fn generic_body_use_after_move_via_let_e0335() {
        // Unbounded `T` is move-only: `let y = x` consumes `x`, so the
        // following `return x` is a use-after-move.
        assert_has_code(
            "fn dup_bug[T](x: T) -> T { let y: T = x; return x; }",
            "E0335",
        );
    }

    #[test]
    fn chained_method_on_consuming_call_no_false_e0335() {
        // `eat(s).grow(2)` — the struct-of-callbacks probe used to
        // type-check the method receiver a first time (marking `s`
        // moved), then method dispatch checked it again and
        // false-positived E0335. The probe now runs only for known
        // fn-pointer field names and rolls back its effects otherwise.
        assert_clean(
            "struct S { opaque v: *u8 }\n\
             impl S { fn drop(ref this) { return; } }\n\
             struct N { k: i32 }\n\
             impl N {\n\
                 fn grow(take this, v: i32) -> N { return N { k: this.k + v }; }\n\
             }\n\
             fn eat(take s: S) -> N { return N { k: 1 }; }\n\
             fn main() -> i32 {\n\
                 let s: S = S { v: 0 as *u8 };\n\
                 let n: N = eat(s).grow(2);\n\
                 return n.k - 3;\n\
             }",
        );
    }

    #[test]
    fn fnptr_field_call_with_moving_receiver_arg_still_works() {
        // The probe's rollback must not break the actual
        // struct-of-callbacks pattern, including through a receiver
        // that itself contains a move.
        assert_clean(
            "struct H { cb: fn(i32) -> i32 }\n\
             struct S { opaque v: *u8 }\n\
             impl S { fn drop(ref this) { return; } }\n\
             fn mk(take s: S) -> H { return H { cb: dbl }; }\n\
             fn dbl(x: i32) -> i32 { return x +% x; }\n\
             fn main() -> i32 {\n\
                 let s: S = S { v: 0 as *u8 };\n\
                 return mk(s).cb(21) - 42;\n\
             }",
        );
    }

    #[test]
    fn e0335_carries_moved_here_label() {
        // The use-after-move diagnostic anchors a "value moved here"
        // label at the consuming site — for a desugared builder block
        // this is what points at the moving modifier line instead of
        // only the (span-reused) item line.
        let diags = check_src(
            "struct S { v: *u8 }\n\
             impl S { fn drop(ref this) { return; } }\n\
             fn eat(take s: S) { return; }\n\
             fn main() -> i32 {\n\
                 let s: S = S { v: 0 as *u8 };\n\
                 eat(s);\n\
                 eat(s);\n\
                 return 0;\n\
             }",
        );
        let e = diags
            .iter()
            .find(|d| d.code.0 == "E0335")
            .expect("expected E0335");
        assert_eq!(e.labels.len(), 1, "expected one moved-here label: {e:#?}");
        assert_eq!(e.labels[0].message, "value moved here");
        // The move happened on the earlier line than the erroring use.
        assert!(
            e.labels[0].span.start.line < e.primary.start.line,
            "label must anchor at the earlier consuming site: {e:#?}"
        );
    }

    #[test]
    fn generic_body_copy_bound_allows_reuse_clean() {
        // `T: Copy` makes `x` bitwise-duplicated, so reusing it is fine
        // (bound-aware Copy). Without it this would false-positive E0335.
        assert_clean("fn dup_ok[T: Copy](x: T) -> T { let y: T = x; return x; }");
    }

    #[test]
    fn generic_body_single_move_is_clean() {
        // Moving a `T` value exactly once (into the return) is fine.
        assert_clean("fn id[T](take x: T) -> T { return x; }");
    }

    #[test]
    fn generic_struct_method_undefined_name_is_e0300_not_ice() {
        // An undefined name inside a generic STRUCT method body was never
        // name-resolved (only concrete + generic-free-fn bodies were), so it
        // sailed through `check` and panicked codegen ("sema validated"). It
        // must now be a clean E0300 at the use site.
        assert_has_code(
            "struct Box[T] { v: T }\n\
             impl Box[T] { fn get(this) -> T { return undefined_name; } }\n\
             fn main() -> i32 { let b: Box[i32] = Box[i32] { v: 1 }; return b.get(); }",
            "E0300",
        );
    }

    #[test]
    fn generic_enum_method_undefined_name_is_e0300_not_ice() {
        assert_has_code(
            "enum Maybe[T] { Some(T), None }\n\
             impl Maybe[T] { fn peek(this) -> i32 { return undefined_name; } }\n\
             fn main() -> i32 { let m: Maybe[i32] = Maybe[i32]::None; return m.peek(); }",
            "E0300",
        );
    }

    #[test]
    fn generic_method_out_of_scope_match_binding_is_e0300() {
        // `v` is bound only in the `Some(v)` arm; using it in the `None` arm is
        // out of scope — the lexically-scoped resolver must catch it.
        assert_has_code(
            "enum Maybe[T] { Some(T), None }\n\
             impl Maybe[T] { fn get(this) -> T { match this { Maybe::Some(v) => { return v; } Maybe::None => { return v; } } } }\n\
             fn main() -> i32 { let m: Maybe[i32] = Maybe[i32]::None; return m.get(); }",
            "E0300",
        );
    }

    #[test]
    fn generic_method_valid_bodies_stay_clean() {
        // A generic method that references params, receiver, locals, for-loop
        // vars, and match-arm bindings correctly must NOT be flagged.
        assert_clean(
            "struct Box[T] { v: T }\n\
             impl Box[T] {\n\
                 fn new(x: T) -> Box[T] { return Box[T] { v: x }; }\n\
                 fn get(this) -> T { return this.v; }\n\
                 fn count(this, extra: i32) -> i32 { var n: i32 = extra; for i in 0..3 { n = n + i; } return n; }\n\
             }\n\
             enum Opt[T] { Some(T), None }\n\
             impl Opt[T] { fn unwrap_or(this, d: T) -> T { match this { Opt::Some(v) => { return v; } Opt::None => { return d; } } } }\n\
             fn main() -> i32 { let b: Box[i32] = Box[i32]::new(5); let o: Opt[i32] = Opt[i32]::None; return b.get() + b.count(1) + o.unwrap_or(0); }",
        );
    }

    #[test]
    fn generic_body_generic_struct_literal_is_clean() {
        // Constructing a generic struct (`Box[T] { ... }`) inside a generic
        // free-fn body resolves and type-checks.
        assert_clean(
            "struct Box[T] { v: T }\n\
             fn wrap[T](take x: T) -> Box[T] { return Box[T] { v: x }; }",
        );
    }

    #[test]
    fn generic_body_receiver_less_interface_method_e0327() {
        // Calling a receiver-less interface method (`make()`) as an instance
        // method (`t.make()`) through a bound is E0327 — the same diagnostic a
        // concrete `p.make()` already gets. Previously this slipped to codegen
        // and panicked ("sema validated instance call").
        assert_has_code(
            "struct P { x: i32 }\n\
             interface Maker { fn make() -> i32; }\n\
             impl P: Maker { fn make() -> i32 { return 7; } }\n\
             fn call_make[T: Maker](t: T) -> i32 { return t.make(); }\n\
             fn main() -> i32 { return 0; }",
            "E0327",
        );
    }

    #[test]
    fn generic_body_use_after_move_into_method_arg_e0335() {
        // Passing a non-Copy value by value to a bound method consumes it, so
        // reusing it afterward is a use-after-move (would double-free at run).
        assert_has_code(
            "struct R { opaque data: *u8 }\n\
             impl R { fn drop(ref this) { return; } }\n\
             struct P {}\n\
             interface Sink { fn sink(this, take r: R); }\n\
             impl P: Sink { fn sink(this, take r: R) { return; } }\n\
             fn use_twice[T: Sink](t: T) -> i32 {\n\
                 let r: R = R { data: { 0 as *u8 } };\n\
                 t.sink(r);\n\
                 let y: R = r;\n\
                 return 0;\n\
             }\n\
             fn main() -> i32 { return 0; }",
            "E0335",
        );
    }

    #[test]
    fn generic_borrow_param_returned_as_owned_e0337() {
        // Returning an unbounded-`T` bare (borrowing) param as an owned value:
        // the caller still owns+drops it, so for a Drop instantiation this is a
        // double-free. Abstract `T` can't be cleared by `ty_carries_drop`
        // (which reads false for `Param`), so a non-Copy `Param` borrow is
        // flagged conservatively.
        assert_has_code("fn leak[T](t: T) -> T { return t; }", "E0337");
    }

    #[test]
    fn generic_copy_borrow_param_returned_clean() {
        // `T: Copy` is bound-aware Copy: returning the borrow bit-copies
        // harmlessly (no destructor), so this is allowed.
        assert_clean("fn ok[T: Copy](t: T) -> T { return t; }");
    }

    #[test]
    fn generic_body_path_assoc_fn_through_bound_clean() {
        // `T::make()` — a receiver-less interface fn called via the path form
        // through `T`'s bound. This is the form E0327 suggests for `t.make()`,
        // so it must resolve (codegen routes each instantiation to the concrete
        // impl's associated fn).
        assert_clean(
            "struct P { x: i32 }\n\
             interface Maker { fn make() -> i32; }\n\
             impl P: Maker { fn make() -> i32 { return 7; } }\n\
             fn call_make[T: Maker]() -> i32 { return T::make(); }\n\
             fn main() -> i32 { return call_make::[P](); }",
        );
    }

    #[test]
    fn generic_body_path_assoc_instance_method_e0327() {
        // `T::val()` where `val` takes `this` is an instance method called via
        // the path form — E0327.
        assert_has_code(
            "struct P { x: i32 }\n\
             interface I { fn val(this) -> i32; }\n\
             impl P: I { fn val(this) -> i32 { return this.x; } }\n\
             fn f[T: I]() -> i32 { return T::val(); }\n\
             fn main() -> i32 { return 0; }",
            "E0327",
        );
    }

    #[test]
    fn generic_body_path_assoc_not_in_bound_e0324() {
        // `T::nope()` — `nope` isn't declared by any of `T`'s bounds: E0324.
        assert_has_code(
            "interface Maker { fn make() -> i32; }\n\
             fn f[T: Maker]() -> i32 { return T::nope(); }\n\
             fn main() -> i32 { return 0; }",
            "E0324",
        );
    }

    #[test]
    fn generic_body_path_assoc_arity_e0308() {
        // Wrong arg count on a path-form bound assoc call: E0308.
        assert_has_code(
            "interface Maker { fn make() -> i32; }\n\
             fn f[T: Maker]() -> i32 { return T::make(99); }\n\
             fn main() -> i32 { return 0; }",
            "E0308",
        );
    }

    #[test]
    fn generic_body_method_arity_mismatch_e0308() {
        // Wrong arg count on a bound method call: E0308, the same as a concrete
        // call. The generic path inherits this from the SHARED checker — it was
        // a gap when the generic path hand-rolled its own arg loop.
        assert_has_code(
            "struct P { x: i32 }\n\
             interface Add { fn add(this, rhs: i32) -> i32; }\n\
             impl P: Add { fn add(this, rhs: i32) -> i32 { return this.x + rhs; } }\n\
             fn call_add[T: Add](t: T) -> i32 { return t.add(2, 3); }\n\
             fn main() -> i32 { return 0; }",
            "E0308",
        );
    }

    #[test]
    fn generic_body_correct_arity_method_clean() {
        assert_clean(
            "struct P { x: i32 }\n\
             interface Add { fn add(this, rhs: i32) -> i32; }\n\
             impl P: Add { fn add(this, rhs: i32) -> i32 { return this.x + rhs; } }\n\
             fn call_add[T: Add](t: T) -> i32 { return t.add(2); }\n\
             fn main() -> i32 { let p: P = P { x: 4 }; return call_add::[P](p); }",
        );
    }

    #[test]
    fn generic_move_self_method_through_bound_on_borrow_e0337() {
        // `t.take()` where `take(take this)` consumes the receiver, but `t` is
        // a bare (borrowing) param: moving it out launders the borrow into an
        // owned value the caller still drops (double-free). Must be E0337 — the
        // receiver path, not just args, runs the move classifier.
        assert_has_code(
            "interface Take { fn take(take this) -> i32; }\n\
             struct R { opaque data: *u8 }\n\
             impl R { fn drop(ref this) { return; } }\n\
             impl R: Take { fn take(take this) -> i32 { return 0; } }\n\
             fn steal[T: Take](t: T) -> i32 { return t.take(); }\n\
             fn main() -> i32 { return 0; }",
            "E0337",
        );
    }

    #[test]
    fn generic_body_move_out_of_borrow_e0337() {
        // Moving a bare (borrowing) parameter by value into a bound method's by-value
        // arg would create a second owner (the caller still drops it): E0337.
        assert_has_code(
            "struct R { opaque data: *u8 }\n\
             impl R { fn drop(ref this) { return; } }\n\
             struct P {}\n\
             interface Sink { fn sink(this, take r: R); }\n\
             impl P: Sink { fn sink(this, take r: R) { return; } }\n\
             fn steal[T: Sink](t: T, r: R) { t.sink(r); return; }\n\
             fn main() -> i32 { return 0; }",
            "E0337",
        );
    }

    // ---- ownership coverage matrix (consuming site × value form) ----
    //
    // ONE invariant — "a value is owned by exactly one place; consuming a
    // non-owning / partial / aliased value is a double-free" — must hold at
    // EVERY value-consuming SITE. Historically each bug was a single missing
    // cell (array/tuple literals, struct/enum construction, assignment,
    // move-self receiver, the generic paths each had to be fixed separately).
    // These grids cross each site with each forbidden value FORM so a NEW site
    // or form can't silently skip a cell — a regression shows up as a failing
    // cell with the exact program that slipped through.

    #[test]
    fn ownership_consume_site_matrix_concrete() {
        const PRELUDE: &str = "\
static DROPS: i32 = 0;\n\
struct R { opaque data: *u8 }\n\
impl R { fn drop(ref this) { { DROPS = DROPS + 1; }; return; } fn sink(take this) -> i32 { return 0; } }\n\
struct H { e: R }\n\
struct W { r: R }\n\
enum E { A(R) }\n\
struct Hdlr { cb: fn(R) -> i32 }\n\
fn mkr() -> R { return R { data: { 0 as *u8 } }; }\n\
fn take(take x: R) -> i32 { return 0; }\n\
fn main() -> i32 { return 0; }\n";

        // (name, body template with `{V}` for the consumed value, returns_R)
        let sites: &[(&str, &str, bool)] = &[
            ("let", "let _x: R = {V};", false),
            ("return", "return {V};", true),
            ("call_arg", "let _c: i32 = take({V});", false),
            ("struct_field", "let _w: W = W { r: {V} };", false),
            ("enum_arg", "let _e: E = E::A({V});", false),
            ("tuple_elem", "let _t: (R, i32) = ({V}, 0);", false),
            ("array_elem", "let _a: [R; 1] = [{V}];", false),
            ("move_self_recv", "let _m: i32 = ({V}).sink();", false),
            ("assign", "var _s: R = mkr(); _s = {V};", false),
            (
                "field_assign",
                "var _hh: H = H { e: mkr() }; _hh.e = {V};",
                false,
            ),
            // indirect calls through a fn-pointer (by-value param = move)
        ];

        // (name, fn params, setup stmts, value expr, expected code | "" = clean)
        let forms: &[(&str, &str, &str, &str, &str)] = &[
            ("borrow_param", "r: R", "", "r", "E0337"),
            (
                "drop_field",
                "",
                "let h: H = H { e: mkr() };",
                "h.e",
                "E0509",
            ),
            ("raw_deref", "p: *R", "", "{ *p }", "E0337"),
            ("safe_rvalue", "", "", "mkr()", ""),
        ];

        for (sname, stmpl, returns_r) in sites {
            for (fname, params, setup, value, expected) in forms {
                let body = stmpl.replace("{V}", value);
                let ret = if *returns_r { " -> R" } else { "" };
                let prog = format!(
                    "{PRELUDE}fn grid_{sname}_{fname}({params}){ret} {{ {setup} {body} }}\n"
                );
                let codes = errors(&prog);
                if expected.is_empty() {
                    assert!(
                        codes.is_empty(),
                        "[{sname} x {fname}] expected CLEAN, got {codes:?}\n--- program ---\n{prog}"
                    );
                } else {
                    assert!(
                        codes.contains(expected),
                        "[{sname} x {fname}] expected {expected}, got {codes:?}\n--- program ---\n{prog}"
                    );
                }
            }
        }
    }

    #[test]
    fn ownership_consume_site_matrix_generic() {
        // Same grid, but the consumed value is an abstract `T` (generic-body
        // checking). Unbounded `T` is move-only → moving a `t: T` into
        // an owned slot is E0337; `T: Copy` is a harmless bit-copy → clean.
        const PRELUDE: &str = "\
struct R { opaque data: *u8 }\n\
impl R { fn drop(ref this) { return; } }\n\
struct GW[U] { v: U }\n\
struct GM { v: i32 }\n\
impl GM { fn take2[U](this, take x: U) -> i32 { return 0; } }\n\
fn gtake[U](take x: U) -> i32 { return 0; }\n\
fn main() -> i32 { return 0; }\n";

        // (name, body template with `{V}`, returns_T)
        let sites: &[(&str, &str, bool)] = &[
            ("let", "let _x: T = {V};", false),
            ("return", "return {V};", true),
            ("call_arg", "let _c: i32 = gtake::[T]({V});", false),
            (
                "generic_method_call",
                "let _w: GM = GM { v: 0 }; let _c: i32 = _w.take2::[T]({V});",
                false,
            ),
            ("struct_field", "let _w: GW[T] = GW[T] { v: {V} };", false),
            ("tuple_elem", "let _t: (T, i32) = ({V}, 0);", false),
            ("array_elem", "let _a: [T; 1] = [{V}];", false),
        ];

        // (name, fn generics, fn params, value, expected | "" = clean)
        let forms: &[(&str, &str, &str, &str, &str)] = &[
            ("borrow_unbounded", "[T]", "t: T", "t", "E0337"),
            ("copy_borrow_safe", "[T: Copy]", "t: T", "t", ""),
        ];

        for (sname, stmpl, returns_t) in sites {
            for (fname, generics, params, value, expected) in forms {
                let body = stmpl.replace("{V}", value);
                let ret = if *returns_t { " -> T" } else { "" };
                let prog = format!(
                    "{PRELUDE}fn g_{sname}_{fname}{generics}({params}){ret} {{ {body} }}\n"
                );
                let codes = errors(&prog);
                if expected.is_empty() {
                    assert!(
                        codes.is_empty(),
                        "[generic {sname} x {fname}] expected CLEAN, got {codes:?}\n--- program ---\n{prog}"
                    );
                } else {
                    assert!(
                        codes.contains(expected),
                        "[generic {sname} x {fname}] expected {expected}, got {codes:?}\n--- program ---\n{prog}"
                    );
                }
            }
        }
    }

    #[test]
    fn ownership_consume_site_matrix_marks_move() {
        // The dual of the grids above: a site must also *mark* a legit move so a
        // LATER use of the same binding is caught (E0335). This is the half that
        // the `[p, q]` codegen double-free was missing — the site moved the
        // value but never recorded it. Move a fresh owned `r` via each site,
        // then read it again.
        const PRELUDE: &str = "\
struct R { opaque data: *u8 }\n\
impl R { fn drop(ref this) { return; } }\n\
struct W { r: R }\n\
enum E { A(R) }\n\
struct Hdlr { cb: fn(R) -> i32 }\n\
fn mkr() -> R { return R { data: { 0 as *u8 } }; }\n\
fn take(take x: R) -> i32 { return 0; }\n\
fn main() -> i32 { return 0; }\n";

        let sites: &[(&str, &str)] = &[
            ("let", "let _x: R = r;"),
            ("call_arg", "let _c: i32 = take(r);"),
            ("struct_field", "let _w: W = W { r: r };"),
            ("enum_arg", "let _e: E = E::A(r);"),
            ("tuple_elem", "let _t: (R, i32) = (r, 0);"),
            ("array_elem", "let _a: [R; 1] = [r];"),
        ];

        for (sname, consume) in sites {
            let prog = format!(
                "{PRELUDE}fn grid_mark_{sname}() {{ let r: R = mkr(); {consume} let _again: R = r; }}\n"
            );
            let codes = errors(&prog);
            assert!(
                codes.contains(&"E0335"),
                "[mark-move {sname}] expected E0335 (use after move), got {codes:?}\n--- program ---\n{prog}"
            );
        }
    }

    #[test]
    fn match_on_an_owned_binding_marks_the_move_matrix() {
        // bugs/moved-from-local-is-readable-and-double-frees.md — a `match`
        // that binds a name consumes an owned Drop-enum binding (codegen has
        // always disarmed its drop pre-switch); sema must record that so a
        // later read is E0335. Before this, the re-read compiled and handed
        // out an already-dropped payload: use-after-free, then double free,
        // with no diagnostic at all.
        //
        // The matrix pins BOTH halves — what now moves, and what deliberately
        // does not, so the fix can't be "reject every second match".
        const PRELUDE: &str = "\
struct R { opaque data: *u8 }\n\
impl R { fn drop(ref this) { return; } }\n\
enum E { A(R), B }\n\
enum Plain { A(i32), B }\n\
struct H { e: E }\n\
fn mkr() -> R { return R { data: { 0 as *u8 } }; }\n\
fn mke() -> E { return E::A(mkr()); }\n\
fn mkp() -> Plain { return Plain::A(1); }\n\
fn main() -> i32 { return 0; }\n";

        // (case, body, expected code | "" = must be clean)
        let cases: &[(&str, &str, &str)] = &[
            // ---- binds a name → consumes ----
            (
                "payload_binding_then_read",
                "let e: E = mke(); match e { E::A(v) => { let _k: R = v; } E::B => {} } let _again: E = e;",
                "E0335",
            ),
            (
                "catchall_binding_then_read",
                "let e: E = mke(); match e { x => { let _k: E = x; } } let _again: E = e;",
                "E0335",
            ),
            // THE reported bug: presence-check match, then match again.
            (
                "bound_presence_check_then_second_match",
                "let e: E = mke(); match e { E::A(_v) => {} E::B => {} } match e { E::A(w) => { let _k: R = w; } E::B => {} }",
                "E0335",
            ),
            // `_v` is this language's PRIVACY convention, not a wildcard — it
            // binds and consumes like any other name. Pinned so nobody
            // "helpfully" makes `_`-prefixed bindings non-consuming.
            (
                "underscore_prefixed_name_still_binds",
                "let e: E = mke(); match e { E::A(_v) => {} E::B => {} } let _again: E = e;",
                "E0335",
            ),
            // The pty shape: the second arm diverges, so only the binding arm
            // falls through — the consumption still reaches past the match
            // (codegen disarms in the pre-switch block, which dominates both).
            (
                "diverging_sibling_arm_still_consumes",
                "let e: E = mke(); match e { E::A(v) => { let _k: R = v; } E::B => { return 1; } } let _again: E = e;",
                "E0335",
            ),
            // (`guard let` desugars to this same binding match — covered by
            // `guard_let_else_cannot_rematch_the_scrutinee` in cpc's e2e
            // suite, since this harness runs sema without `lower`.)
            // ---- binds nothing → does NOT consume ----
            (
                "presence_check_binds_nothing_then_read",
                "let e: E = mke(); match e { E::A(_) => {} E::B => {} } let _again: E = e;",
                "",
            ),
            (
                "wildcard_arm_only_then_read",
                "let e: E = mke(); match e { _ => {} } let _again: E = e;",
                "",
            ),
            // The whole point of keeping the presence check non-consuming:
            // check first, then really match.
            (
                "presence_check_then_consuming_match",
                "let e: E = mke(); match e { E::A(_) => {} E::B => {} } match e { E::A(v) => { let _k: R = v; } E::B => {} }",
                "",
            ),
            (
                "repeated_presence_checks",
                "let e: E = mke(); match e { E::A(_) => {} E::B => {} } match e { E::A(_) => {} E::B => {} } match e { E::A(_) => {} E::B => {} }",
                "",
            ),
            // A drop-free enum has no drop flag for codegen to disarm, so
            // matching it is a pure read and stays re-matchable. Gating on
            // drop is what keeps this rule off ordinary `Option[i32]` code.
            (
                "drop_free_enum_is_rematchable",
                "let p: Plain = mkp(); match p { Plain::A(v) => { let _k: i32 = v; } Plain::B => {} } match p { Plain::A(w) => { let _k2: i32 = w; } Plain::B => {} }",
                "",
            ),
            // A borrowed place is not the match's to consume — the owner still
            // drops it, so re-reading it is fine.
            (
                "borrowed_field_scrutinee_is_not_consumed",
                "let h: H = H { e: mke() }; match h.e { E::A(_) => {} E::B => {} } match h.e { E::A(_) => {} E::B => {} }",
                "",
            ),
            // Re-initialising the binding clears the move, as for any other
            // consuming site.
            (
                "reassignment_after_the_match_reinits",
                "var e: E = mke(); match e { E::A(v) => { let _k: R = v; } E::B => {} } e = mke(); match e { E::A(w) => { let _k2: R = w; } E::B => {} }",
                "",
            ),
        ];

        for (name, body, expected) in cases {
            let prog = format!("{PRELUDE}fn probe_{name}() -> i32 {{ {body} return 0; }}\n");
            let codes = errors(&prog);
            if expected.is_empty() {
                assert!(
                    codes.is_empty(),
                    "[match-move {name}] expected NO errors, got {codes:?}\n--- program ---\n{prog}"
                );
            } else {
                assert!(
                    codes.contains(expected),
                    "[match-move {name}] expected {expected}, got {codes:?}\n--- program ---\n{prog}"
                );
            }
        }
    }

    #[test]
    fn generic_take_arg_consumes_on_both_call_paths() {
        // check_generic_named_call has two branches — turbofish (`sink::[R](r)`)
        // and inference (`sink(r)`) — and the `take` consumption logic must run
        // on BOTH. The inference branch shipped without it: the callee dropped
        // its `take` param while the caller's binding stayed live — a safe-code
        // use-after-free with no unsafe. Grid: call form × consumption shape.
        const PRELUDE: &str = "\
struct R { opaque data: *u8 }\n\
impl R { fn drop(ref this) { return; } }\n\
struct W { r: R }\n\
impl W { fn drop(ref this) { return; } }\n\
fn mkr() -> R { return R { data: { 0 as *u8 } }; }\n\
fn mkw() -> W { return W { r: mkr() }; }\n\
fn sink[T](take x: T) -> i32 { return 0; }\n\
fn peek[T](x: T) -> i32 { return 0; }\n\
fn main() -> i32 { return 0; }\n";

        // (case, body, expected code | "" = clean)
        let cases: &[(&str, &str, &str)] = &[
            // whole-binding move: later use must be E0335 on both forms
            (
                "infer_move",
                "let r: R = mkr(); let _a: i32 = sink(r); let _u: R = r;",
                "E0335",
            ),
            (
                "turbofish_move",
                "let r: R = mkr(); let _a: i32 = sink::[R](r); let _u: R = r;",
                "E0335",
            ),
            // partial move out of a Drop struct: rejected on both forms
            (
                "infer_partial",
                "let w: W = mkw(); let _a: i32 = sink(w.r);",
                "E0509",
            ),
            (
                "turbofish_partial",
                "let w: W = mkw(); let _a: i32 = sink::[R](w.r);",
                "E0509",
            ),
            // bare (non-take) param is a borrow: caller keeps the value
            (
                "infer_bare_borrow",
                "let r: R = mkr(); let _a: i32 = peek(r); let _u: R = r;",
                "",
            ),
            // Copy type args are never consumed
            (
                "infer_copy",
                "let n: i32 = 5; let _a: i32 = sink(n); let _u: i32 = n;",
                "",
            ),
        ];

        for (cname, body, expected) in cases {
            let prog = format!("{PRELUDE}fn case_{cname}() {{ {body} }}\n");
            let codes = errors(&prog);
            if expected.is_empty() {
                assert!(
                    codes.is_empty(),
                    "[generic-take {cname}] expected clean, got {codes:?}\n--- program ---\n{prog}"
                );
            } else {
                assert!(
                    codes.contains(expected),
                    "[generic-take {cname}] expected {expected}, got {codes:?}\n--- program ---\n{prog}"
                );
            }
        }
    }

    // ---- call resolution matrix (form × receiver-ness × context × arity) ----
    //
    // Call RESOLUTION must behave IDENTICALLY whether the type is concrete (`P`)
    // or a generic param (`T: I`). The axes: method-form (`recv.f()`) vs
    // path-form (`Type::f()`); an instance method (declared with `this`) vs an
    // associated fn (no receiver); right vs wrong arity; and unknown names.
    // The `t.make()` / `T::make()` bugs were missing cells of exactly this grid
    // — method-form and path-form are twin resolution surfaces, and a
    // generic-param fix to one needs its twin. This locks the full truth table.

    #[test]
    fn call_resolution_matrix() {
        const PRELUDE: &str = "\
interface I { fn inst(this, a: i32) -> i32; fn assoc(a: i32) -> i32; }\n\
struct P { x: i32 }\n\
impl P: I { fn inst(this, a: i32) -> i32 { return this.x + a; } fn assoc(a: i32) -> i32 { return a; } }\n\
fn main() -> i32 { return 0; }\n";

        // (name, call template — `{V}` value receiver, `{T}` type — needs a
        //  value receiver in scope, expected code | "" = clean)
        let cases: &[(&str, &str, bool, &str)] = &[
            // instance method (`this`): correct via method-form, wrong via path
            ("inst_method_ok", "{V}.inst(1)", true, ""),
            ("inst_method_arity", "{V}.inst(1, 2)", true, "E0308"),
            ("inst_via_path", "{T}::inst(1)", false, "E0327"),
            // associated fn (no receiver): correct via path-form, wrong via method
            ("assoc_path_ok", "{T}::assoc(1)", false, ""),
            ("assoc_path_arity", "{T}::assoc(1, 2)", false, "E0308"),
            ("assoc_via_method", "{V}.assoc(1)", true, "E0327"),
            // unknown name on either surface
            ("unknown_method", "{V}.nope(1)", true, "E0324"),
            ("unknown_path", "{T}::nope(1)", false, "E0324"),
        ];

        for ctx in &["concrete", "generic"] {
            let (vtok, ttok) = if *ctx == "concrete" {
                ("p", "P")
            } else {
                ("t", "T")
            };
            for (name, tmpl, needs_recv, expected) in cases {
                let call = tmpl.replace("{V}", vtok).replace("{T}", ttok);
                let prog = if *ctx == "concrete" {
                    let decl = if *needs_recv {
                        "let p: P = P { x: 4 };"
                    } else {
                        ""
                    };
                    format!(
                        "{PRELUDE}fn c_{name}() -> i32 {{ {decl} let _r: i32 = {call}; return 0; }}\n"
                    )
                } else {
                    let params = if *needs_recv { "t: T" } else { "" };
                    format!(
                        "{PRELUDE}fn g_{name}[T: I]({params}) -> i32 {{ let _r: i32 = {call}; return 0; }}\n"
                    )
                };
                let codes = errors(&prog);
                if expected.is_empty() {
                    assert!(
                        codes.is_empty(),
                        "[{ctx} {name}] expected CLEAN, got {codes:?}\n--- program ---\n{prog}"
                    );
                } else {
                    assert!(
                        codes.contains(expected),
                        "[{ctx} {name}] expected {expected}, got {codes:?}\n--- program ---\n{prog}"
                    );
                }
            }
        }
    }

    #[test]
    fn fn_pointer_coercion_matches_param_conventions() {
        // v0.0.24 #9: a fn-pointer passes its argument BY VALUE, and its type
        // records each param's `take` marker. So a function fits a fn-pointer
        // slot only when it is by-value-compatible AND its convention matches:
        //   - a `take` (consuming) non-Copy param fits a `fn(take R)` slot;
        //   - a Copy-typed param fits either ownership slot (Copy has no
        //     ownership);
        //   - a bare non-Copy param is a read-only borrow passed BY POINTER, so
        //     it cannot ride a by-value fn-pointer at all;
        //   - a `ref` (write-back) param fits ONLY a `fn(ref R)` slot
        //     (handle-projection Tier 2) — for every type, including Copy,
        //     since a ref slot is pointer-passed (`ref n: i32` ⇒ `i32*`).
        const DECLS: &str = "\
struct R { tag: i32 }\n\
impl R { fn drop(ref this) { return; } }\n\
fn peek(r: R) -> i32 { return r.tag; }\n\
fn pm(ref r: R) -> i32 { return 0; }\n\
fn sink(take r: R) -> i32 { return 0; }\n\
fn cnt(n: i32) -> i32 { return n; }\n\
fn bump(ref n: i32) -> i32 { return 0; }\n";
        let borrow_slot = |target: &str| {
            format!("{DECLS}fn u() {{ let _f: fn(R) -> i32 = {target}; return; }}\nfn main() -> i32 {{ return 0; }}")
        };
        let take_slot = |target: &str| {
            format!("{DECLS}fn u() {{ let _f: fn(take R) -> i32 = {target}; return; }}\nfn main() -> i32 {{ return 0; }}")
        };
        let ref_slot = |target: &str| {
            format!("{DECLS}fn u() {{ let _f: fn(ref R) -> i32 = {target}; return; }}\nfn main() -> i32 {{ return 0; }}")
        };
        // Marker must match: a bare param fits a borrowing `fn(R)` slot (the
        // non-Copy value rides by pointer), a `take` param fits a `fn(take R)`
        // slot, a `ref` param fits a `fn(ref R)` slot.
        assert!(
            errors(&borrow_slot("peek")).is_empty(),
            "bare param must fit a borrowing `fn(R)` slot"
        );
        assert!(
            errors(&take_slot("sink")).is_empty(),
            "take param must fit a `fn(take R)` slot"
        );
        assert!(
            errors(&ref_slot("pm")).is_empty(),
            "ref param must fit a `fn(ref R)` slot"
        );
        // Mismatched markers are rejected in both directions.
        assert!(
            errors(&take_slot("peek")).contains(&"E0312"),
            "bare worker must not fit a `fn(take R)` slot"
        );
        assert!(
            errors(&borrow_slot("sink")).contains(&"E0312"),
            "take worker must not fit a borrowing `fn(R)` slot"
        );
        // `ref` is exact-match: a ref param rejects a non-ref slot, and a
        // non-ref param rejects a ref slot.
        assert!(
            errors(&borrow_slot("pm")).contains(&"E0312"),
            "`ref` param must not fit a borrowing `fn(R)` slot"
        );
        assert!(
            errors(&take_slot("pm")).contains(&"E0312"),
            "`ref` param must not fit a `fn(take R)` slot"
        );
        assert!(
            errors(&ref_slot("peek")).contains(&"E0312"),
            "bare param must not fit a `fn(ref R)` slot"
        );
        assert!(
            errors(&ref_slot("sink")).contains(&"E0312"),
            "take param must not fit a `fn(ref R)` slot"
        );
        // A Copy-typed param rides either ownership slot (Copy has no
        // ownership) — but the ref marker still must match exactly (ABI).
        let prog_copy = format!("{DECLS}fn u() {{ let _f: fn(i32) -> i32 = cnt; return; }}\nfn main() -> i32 {{ return 0; }}");
        assert!(errors(&prog_copy).is_empty(), "Copy param must be accepted");
        let prog_copy_ref = format!("{DECLS}fn u() {{ let _f: fn(ref i32) -> i32 = bump; return; }}\nfn main() -> i32 {{ return 0; }}");
        assert!(
            errors(&prog_copy_ref).is_empty(),
            "Copy ref param must fit a `fn(ref i32)` slot"
        );
        let prog_copy_ref_mismatch = format!("{DECLS}fn u() {{ let _f: fn(ref i32) -> i32 = cnt; return; }}\nfn main() -> i32 {{ return 0; }}");
        assert!(
            errors(&prog_copy_ref_mismatch).contains(&"E0312"),
            "bare Copy param must not fit a `fn(ref i32)` slot (pointer-passed)"
        );
        let prog_copy_bare_mismatch = format!("{DECLS}fn u() {{ let _f: fn(i32) -> i32 = bump; return; }}\nfn main() -> i32 {{ return 0; }}");
        assert!(
            errors(&prog_copy_bare_mismatch).contains(&"E0312"),
            "Copy ref param must not fit a bare `fn(i32)` slot (pointer-passed)"
        );
    }

    #[test]
    fn fn_pointer_ref_param_call_requires_var_place() {
        // Handle-projection Tier 2: calling through a `fn(ref R)` pointer
        // writes back to the caller's place, so the argument must be a `var`
        // (writable) place — same E0328 rule as a named `ref` param.
        const DECLS: &str = "\
struct R { tag: i32 }\n\
impl R { fn drop(ref this) { return; } }\n\
fn pm(ref r: R) -> i32 { return 0; }\n";
        let ok = format!(
            "{DECLS}fn u() {{ let f: fn(ref R) -> i32 = pm; var r: R = R {{ tag: 1 }}; let _n: i32 = f(r); return; }}\nfn main() -> i32 {{ return 0; }}"
        );
        assert!(
            errors(&ok).is_empty(),
            "var arg through a `fn(ref R)` pointer must be accepted"
        );
        let frozen = format!(
            "{DECLS}fn u() {{ let f: fn(ref R) -> i32 = pm; let r: R = R {{ tag: 1 }}; let _n: i32 = f(r); return; }}\nfn main() -> i32 {{ return 0; }}"
        );
        assert!(
            errors(&frozen).contains(&"E0328"),
            "let arg through a `fn(ref R)` pointer must reject with E0328"
        );
    }

    // ---- `f16` literal suffix ----

    #[test]
    fn f16_literal_types_as_f16() {
        // `1.5f16` is an f16, and an unsuffixed literal coerces to an f16
        // annotation.
        assert!(errors("fn f() -> i32 { let h: f16 = 1.5f16; return 0; }").is_empty());
        assert!(errors("fn f() -> i32 { let h: f16 = 1.5; return 0; }").is_empty());
    }

    // ---- `c"..."` C-string literals (type `*u8`) ----

    #[test]
    fn cstring_literal_types_as_raw_ptr() {
        // c"..." is `*u8` and safe to *form* (a pointer to static data) — a
        // plain binding (only dereferencing it is a raw operation).
        assert!(errors("fn f() -> i32 { let p: *u8 = c\"hi\"; return 0; }").is_empty());
        // Binding it to a non-pointer is a type mismatch.
        assert!(errors("fn f() -> i32 { let n: i32 = c\"hi\"; return 0; }").contains(&"E0302"));
    }

    // ---- v0.0.8 Phase 4: `env!("NAME")` compile-time env-var read ----

    #[test]
    fn env_macro_resolves_set_var_to_str() {
        // Positive case: var is set in the compiler's environment, so
        // `env!("NAME")` resolves to a `str` value at sema time.
        std::env::set_var("CPC_TEST_ENV_VAR", "from-test");
        assert_clean(
            "fn main() -> i32 {\n\
                 let v: str = #env(\"CPC_TEST_ENV_VAR\");\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn env_macro_missing_var_e0876() {
        // Negative case: env var not set → E0876 at sema time.
        std::env::remove_var("CPC_TEST_DEFINITELY_MISSING_99");
        assert_only_code(
            "fn main() -> i32 {\n\
                 let _v: str = #env(\"CPC_TEST_DEFINITELY_MISSING_99\");\n\
                 return 0;\n\
             }",
            "E0876",
        );
    }

    // ---- v0.0.8 post-bench-gap: `restrict` param marker (E0411) ----

    #[test]
    fn restrict_on_raw_pointer_param_clean() {
        // `restrict p: *T` is well-formed.
        assert_clean(
            "fn axpy(n: usize, restrict x: *f32, restrict y: *f32) { return; }\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn restrict_on_integer_param_e0411() {
        // E0411: `restrict x: i32` — restrict requires `*T`.
        assert_only_code(
            "fn bad(restrict x: i32) -> i32 { return x; }\n\
             fn main() -> i32 { return bad(0); }",
            "E0411",
        );
    }

    #[test]
    fn restrict_on_struct_param_e0411() {
        // E0411: `restrict s: Point` — restrict requires `*T`.
        assert_only_code(
            "struct Point { x: i32, y: i32 }\n\
             fn bad(restrict s: Point) -> i32 { return s.x; }\n\
             fn main() -> i32 { let p: Point = Point { x: 1, y: 2 }; return bad(p); }",
            "E0411",
        );
    }

    // ---- #addr_of(x) intrinsic ----

    // ---- v0.0.9 follow-up: `x: T` parameter marker ----

    #[test]
    fn borrow_param_marker_clean() {
        // `x: T` is an explicit form of the current shared
        // by-value default. Semantically a no-op for v0.0.9; reserved
        // so a future Phase 1 default-move flip has a clean opt-out.
        assert_clean(
            "fn add(a: i32, b: i32) -> i32 { return a + b; }\n\
             fn main() -> i32 { return add(2, 3); }",
        );
    }

    #[test]
    fn addr_of_local_in_unsafe_clean() {
        // The happy path: a bare `#addr_of(x)` returns `*T` for a
        // local binding (no `unsafe` wrapper). Non-Ident / wrong-arity cases
        // are checked separately below.
        assert_clean(
            "extern fn use_ptr(p: *i64);\n\
             fn main() -> i32 {\n\
                 let t: i64 = 0;\n\
                 { use_ptr(#addr_of(t)); }\n\
                 return 0;\n\
             }",
        );
    }

    // v0.0.12 G-025: `#addr_of` accepts any place expression — fields,
    // indices, derefs, and chains. Call results / arithmetic / etc.
    // remain rejected because they have no stable address.

    #[test]
    fn addr_of_field_access_clean_g025() {
        assert_clean(
            "struct P { x: i32, y: i32 }\n\
             fn main() -> i32 {\n\
                 let p: P = P { x: 5, y: 6 };\n\
                 let q: *i32 = { #addr_of(p.x) };\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn addr_of_deref_field_clean_g025() {
        assert_clean(
            "struct P { x: i32 }\n\
             fn main() -> i32 {\n\
                 let p: P = P { x: 5 };\n\
                 let pp: *P = { #addr_of(p) };\n\
                 let q: *i32 = { #addr_of((*pp).x) };\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn addr_of_array_index_clean_g025() {
        assert_clean(
            "fn main() -> i32 {\n\
                 let a: [i32; 4] = [10, 20, 30, 40];\n\
                 let q: *i32 = { #addr_of(a[2]) };\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn addr_of_deref_clean_g025() {
        assert_clean(
            "fn main() -> i32 {\n\
                 let n: i64 = 5;\n\
                 let p: *i64 = { #addr_of(n) };\n\
                 let q: *i64 = { #addr_of(*p) };\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn addr_of_call_result_rejected_e0302_g025() {
        // Call result is an rvalue — no stable address.
        assert_only_code(
            "fn foo() -> i32 { return 42; }\n\
             fn main() -> i32 {\n\
                 let q: *i32 = { #addr_of(foo()) };\n\
                 return 0;\n\
             }",
            "E0302",
        );
    }

    #[test]
    fn addr_of_arithmetic_rejected_e0302_g025() {
        assert_only_code(
            "fn main() -> i32 {\n\
                 let x: i32 = 1;\n\
                 let q: *i32 = { #addr_of(x +% 1) };\n\
                 return 0;\n\
             }",
            "E0302",
        );
    }

    // v0.0.12 G-024: `is_null()` / `is_not_null()` on raw pointers.
    // Safe to call (just compares the bit pattern); returns `bool`.

    #[test]
    fn is_null_on_raw_ptr_clean_g024() {
        assert_clean(
            "fn main() -> i32 {\n\
                 let p: *u8 = { 0 as *u8 };\n\
                 if p.is_null() { return 1; }\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn is_not_null_on_raw_ptr_clean_g024() {
        assert_clean(
            "fn main() -> i32 {\n\
                 let p: *u8 = { 0 as *u8 };\n\
                 if p.is_not_null() { return 1; }\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn is_null_does_not_require_unsafe_g024() {
        // is_null inspects the bit pattern; no memory access, no unsafe.
        assert_clean(
            "fn need_ptr() -> *u8 { return { 0 as *u8 }; }\n\
             fn main() -> i32 {\n\
                 let p: *u8 = need_ptr();\n\
                 if p.is_null() { return 0; }\n\
                 return 1;\n\
             }",
        );
    }

    // v0.0.12 G-026: `()` resolves to `Ty::Unit` and round-trips
    // through generic instantiation (e.g. `spawn::[()]`).

    // v0.0.12 G-028 (llama.cplus G-026): `#zero::[T]()` and `*T.write_zeroed()`
    // for explicit zero-fill — closes the C99 partial-init / silent-garbage gap.

    #[test]
    fn zero_intrinsic_returns_type_clean_g028() {
        assert_clean(
            "struct P { x: i32, y: i32 }\n\
             fn main() -> i32 { let _p: P = #zero::[P](); return 0; }",
        );
    }

    #[test]
    fn zero_intrinsic_primitive_clean_g028() {
        assert_clean("fn main() -> i32 { let _x: i64 = #zero::[i64](); return 0; }");
    }

    #[test]
    fn zero_intrinsic_no_type_arg_rejected_e0501_g028() {
        let codes = errors("fn main() -> i32 { let _x: i32 = #zero(); return 0; }");
        assert!(codes.contains(&"E0501"));
    }

    #[test]
    fn write_zeroed_on_raw_ptr_clean_g028() {
        assert_clean(
            "extern fn malloc(n: usize) -> *u8;\n\
             struct P { x: i32 }\n\
             fn main() -> i32 {\n\
                 let p: *P = { malloc(#size_of::[P]()) as *P };\n\
                 { p.write_zeroed(); }\n\
                 return 0;\n\
             }",
        );
    }

    // v0.0.12 G-030 (llama.cplus G-029): `__cplus_atomic_fence_<ord>`
    // memory fence intrinsic. A bare expression (no `unsafe` wrapper); 0 args.

    #[test]
    fn atomic_fence_seqcst_in_unsafe_clean_g030() {
        assert_clean(
            "fn main() -> i32 {\n\
                 { #atomic_fence_seqcst(); }\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn atomic_fence_relaxed_clean_g030() {
        // Relaxed is accepted by sema (it's a no-op at codegen).
        assert_clean(
            "fn main() -> i32 {\n\
                 { #atomic_fence_relaxed(); }\n\
                 return 0;\n\
             }",
        );
    }
    #[test]
    fn atomic_fence_with_args_e0308_g030() {
        let codes = errors(
            "fn main() -> i32 {\n\
                 { #atomic_fence_seqcst(1 as i32); }\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0308"));
    }

    // v0.0.12 G-031 (llama.cplus G-030): `#cpu_relax()` spin-loop hint.
    // Safe; 0 args; 0 type args; returns unit.

    #[test]
    fn cpu_relax_clean_g031() {
        assert_clean(
            "fn main() -> i32 {\n\
                 var i: i32 = 0;\n\
                 while i < 3 { #cpu_relax(); i = i +% 1; }\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn cpu_relax_with_args_e0308_g031() {
        let codes = errors("fn main() -> i32 { #cpu_relax(1 as i32); return 0; }");
        assert!(codes.contains(&"E0308"));
    }

    // v0.0.12 G-033 (llama.cplus G-032): `#zero::[T]()` accepted in
    // const/static initializer position. Closes the BSS-zero global case.

    #[test]
    fn zero_in_static_init_clean_g033() {
        assert_clean(
            "#[repr(C)] struct S { a: i32, b: i64 }\n\
             static T: S = #zero::[S]();\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn zero_in_static_mut_init_clean_g033() {
        assert_clean(
            "static TABLE: [i32; 16] = #zero::[[i32; 16]]();\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn zero_in_const_init_clean_g033() {
        // const FOO also accepts #zero (papercut they hit in
        // threadpool.cplus). Same shape as static.
        assert_clean(
            "const ZEROS: [u8; 64] = #zero::[[u8; 64]]();\n\
             fn main() -> i32 { return 0; }",
        );
    }

