    // ---- TEXT.1 retired: formerly unsafe fn call gate ----
    #[test]
    fn unsafe_free_fn_call_inside_unsafe_clean_text1() {
        assert_clean(
            "fn danger() -> i32 { return 1; }\n\
             fn main() -> i32 { let d: i32 = { danger() }; return d; }",
        );
    }

    #[test]
    fn safe_free_fn_call_needs_no_unsafe_text1() {
        assert_clean(
            "fn calm() -> i32 { return 1; }\n\
             fn main() -> i32 { let d: i32 = calm(); return d; }",
        );
    }
    #[test]
    fn unsafe_fn_to_fn_ptr_inside_unsafe_clean() {
        // Take the pointer in a plain block (where the `let` annotation supplies
        // the `fn(...)` type hint). `unsafe fn` and the `unsafe` block it once
        // required are retired (TEXT.1), so `danger` is an ordinary fn here.
        assert_clean(
            "fn danger(x: i32) -> i32 { return x + 1; }\n\
             fn main() -> i32 {\n\
                 let r: i32 = {\n\
                     let f: fn(i32) -> i32 = danger;\n\
                     f(6)\n\
                 };\n\
                 return r;\n\
             }",
        );
    }

    #[test]
    fn safe_fn_to_fn_ptr_needs_no_unsafe() {
        // A pointer to a SAFE fn is unaffected.
        assert_clean(
            "fn add1(x: i32) -> i32 { return x + 1; }\n\
             fn main() -> i32 { let f: fn(i32) -> i32 = add1; return f(6); }",
        );
    }
    #[test]
    fn unsafe_method_call_inside_unsafe_clean_text1() {
        assert_clean(
            "struct Counter { n: i32 }\n\
             impl Counter { fn raw_get(this) -> i32 { return this.n; } }\n\
             fn main() -> i32 {\n\
                 let c: Counter = Counter { n: 7 };\n\
                 let v: i32 = { c.raw_get() };\n\
                 return v;\n\
             }",
        );
    }

    #[test]
    fn safe_method_beside_unsafe_method_needs_no_unsafe_text1() {
        // Every method is callable without a wrapping block (`unsafe fn` retired).
        assert_clean(
            "struct Counter { n: i32 }\n\
             impl Counter {\n\
                 fn raw_get(this) -> i32 { return this.n; }\n\
                 fn safe_get(this) -> i32 { return this.n; }\n\
             }\n\
             fn main() -> i32 {\n\
                 let c: Counter = Counter { n: 7 };\n\
                 let v: i32 = c.safe_get();\n\
                 return v;\n\
             }",
        );
    }
    #[test]
    fn unsafe_enum_method_call_inside_unsafe_clean_text1() {
        assert_clean(
            "enum E { A, B }\n\
             impl E { fn raw(this) -> i32 { return 1; } }\n\
             fn main() -> i32 {\n\
                 let e: E = E::A;\n\
                 let v: i32 = { e.raw() };\n\
                 return v;\n\
             }",
        );
    }
    #[test]
    fn unsafe_generic_free_fn_call_inside_unsafe_clean_text1() {
        assert_clean(
            "fn danger[T](take x: T) -> T { return x; }\n\
             fn main() -> i32 { let d: i32 = { danger::[i32](1) }; return d; }",
        );
    }

    // ---- TEXT.R1: literal → `Text` coercion (let-scoped) ----

    #[test]
    fn lang_string_literal_in_typed_let_clean_text_r1() {
        // `opaque ptr` accounts for the raw-pointer field without a freeing
        // drop (this is a type-check-only test, no codegen).
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { let s: Text = \"x\"; return 0; }",
        );
    }

    #[test]
    fn lang_string_literal_as_owning_arg_clean_text_r1c() {
        // A literal for an owning (by-value) `Text` param constructs an owned
        // Text — coercion now covers the arg site.
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn take(t: Text) -> i32 { return 0; }\n\
             fn main() -> i32 { return take(\"x\"); }",
        );
    }

    #[test]
    fn lang_string_literal_as_mut_arg_errors_text_r1c() {
        // Coercion is scoped to *owning* params; a literal for a `ref` param has
        // no place to mutate and still mismatches (E0302).
        let codes = errors(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn take(ref t: Text) -> i32 { return 0; }\n\
             fn main() -> i32 { return take(\"x\"); }",
        );
        assert!(codes.contains(&"E0302"));
    }

    #[test]
    fn lang_string_literal_in_return_clean_text_r1c() {
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn label() -> Text { return \"OK\"; }\n\
             fn main() -> i32 { let t: Text = label(); return 0; }",
        );
    }

    #[test]
    fn non_lang_struct_literal_in_return_errors_text_r1c() {
        // Return coercion is only for the designated string type.
        let codes = errors(
            "struct Other { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn make() -> Other { return \"x\"; }\n\
             fn main() -> i32 { let o: Other = make(); return 0; }",
        );
        assert!(codes.contains(&"E0302"));
    }

    #[test]
    fn to_string_produces_text_clean_text_r3b() {
        // `.to_text()` produces the designated type, so it matches a `Text`
        // annotation (no E0302) — consistent with interpolation.
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { let n: i32 = 1; let s: Text = n.to_text(); return 0; }",
        );
    }

    // v0.0.19 import-gating: owned strings require `import "stdlib/text"` (which
    // brings the `#[lang("string")]` `Text` struct into scope). Without it,
    // `.to_text()` and string interpolation error E0613 instead of silently
    // producing the legacy internal owned-string type.
    #[test]
    fn to_text_without_text_import_rejected_e0613_v0019() {
        let codes = errors("fn f() -> i32 { let n: i32 = 1; let s = n.to_text(); return 0; }");
        assert!(codes.contains(&"E0613"), "expected E0613, got: {codes:?}");
    }

    #[test]
    fn interpolation_without_text_import_rejected_e0613_v0019() {
        let codes = errors(
            "fn f(x: i32) -> i32 { let s = \"v=${x}\"; return 0; } fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0613"), "expected E0613, got: {codes:?}");
    }

    #[test]
    fn interp_fragment_diagnostic_spans_point_into_parent_source() {
        // A sema diagnostic on an interpolated `${...}` sub-expression must
        // carry the PARENT-file span (the re-lexed fragment tokens are
        // rebased), not offset 0 of file 0 — the v1 shortcut that anchored
        // every such diagnostic at the top of the wrong file.
        let src = "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
                   fn f() -> i32 { let b: Text = \"v=${undefned}\"; return 0; }";
        let diags = check_src(src);
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0300")
            .expect("undefined name inside ${...} must be E0300");
        let want = src.find("undefned").unwrap() as u32;
        assert_eq!(
            d.primary.start.byte, want,
            "diagnostic must anchor at the fragment's parent-file offset, got {:?}",
            d.primary.start
        );
    }

    // With the lang-string struct in scope (the import's effect), both are clean.
    #[test]
    fn to_text_and_interpolation_with_text_in_scope_clean_v0019() {
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn f(x: i32) -> i32 { let a: Text = x.to_text(); let b: Text = \"v=${x}\"; return 0; }",
        );
    }

    // A plain string literal with no `${...}` is a `str` — never gated.
    #[test]
    fn plain_string_literal_without_text_import_clean_v0019() {
        assert_clean("fn f() -> str { return \"hello\"; }");
    }

    // v0.0.19: the blessed conversion method was renamed `to_string` → `to_text`
    // (tracking the surviving owned type `Text` after `string` was removed). The
    // old `.to_string()` spelling is no longer blessed — on a primitive it's now
    // an unknown method (E0324).
    #[test]
    fn to_string_method_spelling_rejected_v0019() {
        let codes = errors(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { let n: i32 = 1; let s: Text = n.to_string(); return 0; }",
        );
        assert!(codes.contains(&"E0324"), "expected E0324, got: {codes:?}");
    }

    // v0.0.19: a source-level `string` (type position) still errors E0303
    // (the type was removed in v0.0.18), but the diagnostic now carries a
    // help note pointing at the stdlib `Text` replacement.
    #[test]
    fn string_type_e0303_suggests_text_v0019() {
        let diags = check_src("fn main() -> i32 { let s: string = 0; return 0; }");
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0303" && d.message.contains("string"))
            .expect("expected E0303 on `string`");
        assert!(
            d.notes.iter().any(|n| n.contains("Text"))
                && d.notes.iter().any(|n| n.contains("stdlib/text")),
            "expected Text/import note, got {:?}",
            d.notes
        );
    }

    // The `string::new` / `string::with_capacity` path form also hits the
    // unknown-type path and gets the same help note.
    #[test]
    fn string_path_call_e0303_suggests_text_v0019() {
        let diags = check_src("fn main() -> i32 { let s: i32 = string::new(); return 0; }");
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0303" && d.message.contains("string"))
            .expect("expected E0303 on `string::new`");
        assert!(
            d.notes.iter().any(|n| n.contains("Text")),
            "expected Text note, got {:?}",
            d.notes
        );
    }

    // A different unknown type does NOT get the Text note (the note is
    // specific to the removed `string`).
    #[test]
    fn other_unknown_type_e0303_has_no_text_note_v0019() {
        let diags = check_src("fn main() -> i32 { let s: Frobnicate = 0; return 0; }");
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0303")
            .expect("expected E0303");
        assert!(
            d.notes.is_empty(),
            "unexpected notes on unrelated unknown type: {:?}",
            d.notes
        );
    }

    // GAP 3 (v0.0.19): an operator type error whose message names the *left*
    // operand's type pins its span to that operand, not the whole `a op b`
    // expression — so an agent reading the JSON span lands on the operand to
    // fix. Here `a` is the single offending char.
    #[test]
    fn operator_type_error_span_pins_left_operand_gap3() {
        let src = "fn main() -> i32 { \
                   let a: bool = true; let b: i32 = 2; \
                   let c: i32 = a + b; return c; }";
        let diags = check_src(src);
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0302" && d.message.contains("numeric operands"))
            .expect("expected E0302 numeric-operands error");
        assert_eq!(
            d.primary.end.byte - d.primary.start.byte,
            1,
            "span should cover only the left operand `a`, got {:?}..{:?}",
            d.primary.start,
            d.primary.end
        );
    }

