    fn restrict_on_method_param_clean() {
        // Method params accept `restrict *T` the same as free fns.
        assert_clean(
            "struct State { v: i32 }\n\
             impl State { fn fill(this, restrict p: *u8, n: usize) { return; } }\n\
             fn main() -> i32 { return 0; }",
        );
    }

