    // Regression: calling a `ref this` method through a raw-pointer deref is a
    // write through `*q` (a writable place — raw pointers are mutable-capable),
    // exactly like `(*q).field = v` is already allowed. `is_writable_place_quiet`
    // had no Deref arm and spuriously raised E0328; it now mirrors
    // `target_is_writable_place`.
    #[test]
    fn mut_method_through_raw_ptr_deref_clean() {
        let codes = errors(
            "struct P { x: i32 }\n\
             impl P { fn bump(ref this) { this.x = this.x + 1; } }\n\
             fn via_ptr(p: *u8) { let q: *P = { p as *P }; (*q).bump(); return; }",
        );
        assert!(
            !codes.contains(&"E0328"),
            "spurious E0328 on `(*ptr).mut_method()`: {codes:?}"
        );
    }

    // Same fix, the other call site: passing a raw-pointer deref `*q` to a
    // `ref` parameter (which shares `is_writable_place_quiet`).
    #[test]
    fn ref_arg_through_raw_ptr_deref_clean() {
        let codes = errors(
            "fn takes_ref(ref n: i32) { n = n + 1; }\n\
             fn via_ptr(p: *u8) { let q: *i32 = { p as *i32 }; takes_ref(*q); return; }",
        );
        assert!(
            !codes.contains(&"E0328"),
            "spurious E0328 on `ref` arg `(*ptr)`: {codes:?}"
        );
    }

    // Struct destructuring: `let TYPE { fields } = expr;` binds the fields by
    // moving them out (sound where a bare field move is E0509-rejected).
    #[test]
    fn destructure_binds_fields_clean() {
        let codes = errors(
            "struct Pair { a: i32, b: i32 }\n\
             fn f(take p: Pair) -> i32 { let Pair { a, b } = p; return a + b; }",
        );
        assert!(
            codes.is_empty(),
            "plain destructure should be clean: {codes:?}"
        );
    }

    // A struct with an explicit `fn drop` cannot be destructured (its destructor
    // must run as a unit) — E0509.
    #[test]
    fn destructure_explicit_drop_e0509() {
        let codes = errors(
            "struct R { x: i32 }\n\
             impl R { fn drop(ref this) { return; } }\n\
             fn f(take r: R) -> i32 { let R { x } = r; return x; }",
        );
        assert!(
            codes.contains(&"E0509"),
            "destructuring an explicit-drop struct should be E0509: {codes:?}"
        );
    }

    // Every field must be bound (no `..` in the MVP) — E0321.
    #[test]
    fn destructure_non_exhaustive_e0321() {
        let codes = errors(
            "struct Pair { a: i32, b: i32 }\n\
             fn f(take p: Pair) -> i32 { let Pair { a } = p; return a; }",
        );
        assert!(
            codes.contains(&"E0321"),
            "non-exhaustive destructure should be E0321: {codes:?}"
        );
    }

