    // ---- Phase 7 slice 7GEN.5e: source-level generic-enum patterns ----

    #[test]
    fn generic_enum_pattern_with_explicit_type_args_clean() {
        // The headline of 7GEN.5e: `Option[i32]::Some(v)` in pattern
        // position. No mangled name in source.
        assert_clean(
            "#[lang(\"option\")] enum Option[T] { Some(T), None } \
             fn unwrap_or(o: Option[i32], default: i32) -> i32 { \
                 return match o { \
                     Option[i32]::Some(v) => v, \
                     Option[i32]::None => default, \
                 }; \
             } \
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn generic_enum_pattern_unqualified_clean() {
        // Type-directed: `Option::Some(v)` with no type args resolves
        // against an `Option[i32]` scrutinee via the EnumDef's
        // `generic_base` field.
        assert_clean(
            "#[lang(\"option\")] enum Option[T] { Some(T), None } \
             fn unwrap_or(o: Option[i32], default: i32) -> i32 { \
                 return match o { \
                     Option::Some(v) => v, \
                     Option::None => default, \
                 }; \
             } \
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn generic_enum_pattern_wrong_type_arg_e0341() {
        // `Option[bool]::Some` against an `Option[i32]` scrutinee
        // resolves to a different EnumId and is rejected.
        let codes = errors(
            "#[lang(\"option\")] enum Option[T] { Some(T), None } \
             fn pick(o: Option[i32]) -> i32 { \
                 return match o { \
                     Option[bool]::Some(_) => 1, \
                     Option[bool]::None => 0, \
                 }; \
             } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0341"), "expected E0341, got: {codes:?}");
    }

    #[test]
    fn diverging_if_branch_does_not_constrain_type() {
        // (A) 2026-07-08: a diverging branch (`return`/`break`/`continue`)
        // yields no value, so `if` takes the surviving branch's type instead of
        // firing a spurious `() vs T` E0302.
        assert_clean(
            "fn f(c: bool) -> i32 { \
                 let x: i32 = if c { return 1; } else { 5 }; \
                 return x; \
             } \
             fn main() -> i32 { return f(true); }",
        );
    }

    #[test]
    fn diverging_match_arm_does_not_constrain_type() {
        // A diverging arm body must not be checked against the expected result
        // type (it carries no value) — the common `None => { return .. }` shape.
        assert_clean(
            "enum Opt[T] { Some(T), None } \
             fn f(o: Opt[i32]) -> i32 { \
                 let x: i32 = match o { \
                     Opt[i32]::Some(v) => v, \
                     Opt[i32]::None => { return 0; } \
                 }; \
                 return x; \
             } \
             fn main() -> i32 { return f(Opt[i32]::None); }",
        );
    }

    #[test]
    fn diverging_tail_match_is_not_an_implicit_tail() {
        // A fn-body tail whose arms all diverge is terminal control flow, not an
        // implicit tail VALUE: no E0333, no `() vs T`. (Codegen caps the
        // unreachable merge with `unreachable`; the run path is covered e2e.)
        assert_clean(
            "enum Opt[T] { Some(T), None } \
             fn f(o: Opt[i32]) -> i32 { \
                 match o { \
                     Opt[i32]::Some(v) => { return v; } \
                     Opt[i32]::None => { return 0; } \
                 } \
             } \
             fn main() -> i32 { return f(Opt[i32]::None); }",
        );
    }

    #[test]
    fn generic_enum_pattern_raw_ptr_type_arg_clean() {
        // vec-of-raw-pointers bug (2026-07-08): instantiating a generic
        // struct with a raw-pointer arg (`Holder[*Node]`) drives the
        // pattern-discovery pass over the impl body's `Opt[T]` / `Opt[*T]`
        // patterns with `T := *Node`. The AST substitution used to render
        // the pointer arg as the unresolvable `<raw-ptr>` Path and fire
        // E0303; it must build a structured `TypeKind::RawPtr` instead.
        // Mirrors the `Option[*T]` patterns in stdlib Vec's each/fold/iter.
        assert_clean(
            "enum Opt[T] { Some(T), None } \
             struct Node { v: i64 } \
             struct Holder[T] { n: i64 } \
             impl Holder[T] { \
                 fn probe(this, o: Opt[T]) -> i64 { \
                     let q: Opt[*T] = Opt[*T]::None; \
                     let a: i64 = match o { \
                         Opt[T]::Some(_) => 1, \
                         Opt[T]::None => 0, \
                     }; \
                     let b: i64 = match q { \
                         Opt[*T]::Some(_) => 1, \
                         Opt[*T]::None => 0, \
                     }; \
                     return a + b; \
                 } \
             } \
             fn main() -> i32 { \
                 let h: Holder[*Node] = Holder[*Node] { n: 3 }; \
                 let o: Opt[*Node] = Opt[*Node]::None; \
                 return (h.probe(o) - 1) as i32; \
             }",
        );
    }

    #[test]
    fn generic_enum_pattern_raw_ptr_wrong_arg_e0341() {
        // Structured pointer args must still participate in pattern/scrutinee
        // mismatch detection: `Opt[*bool]::Some` against an `Opt[*Node]`
        // scrutinee resolves to a different EnumId and is rejected.
        let codes = errors(
            "enum Opt[T] { Some(T), None } \
             struct Node { v: i64 } \
             fn pick(o: Opt[*Node]) -> i32 { \
                 return match o { \
                     Opt[*bool]::Some(_) => 1, \
                     Opt[*bool]::None => 0, \
                 }; \
             } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0341"), "expected E0341, got: {codes:?}");
    }

    #[test]
    fn generic_enum_pattern_fn_ptr_type_arg_clean() {
        // Same lossy-render path as the raw-pointer case: a fn-ptr type arg
        // used to collapse to `<fn-ptr>` during pattern-discovery
        // substitution. Must round-trip structurally.
        assert_clean(
            "enum Opt[T] { Some(T), None } \
             struct Holder[T] { n: i64 } \
             impl Holder[T] { \
                 fn probe(this, o: Opt[T]) -> i64 { \
                     return match o { \
                         Opt[T]::Some(_) => 1, \
                         Opt[T]::None => 0, \
                     }; \
                 } \
             } \
             fn main() -> i32 { \
                 let h: Holder[fn(i64) -> i64] = Holder[fn(i64) -> i64] { n: 3 }; \
                 let o: Opt[fn(i64) -> i64] = Opt[fn(i64) -> i64]::None; \
                 return (h.probe(o) - 1) as i32; \
             }",
        );
    }

