    #[test]
    fn bound_violation_at_generic_fn_call_e0502() {
        // `fn max[T: Ord]` called with a type that doesn't impl Ord.
        let codes = errors(
            "fn max[T: Ord](take a: T, b: T) -> T { return a; } \
             struct Point { x: i32 } \
             fn main() -> i32 { \
                 let p: Point = Point { x: 0 }; \
                 let q: Point = Point { x: 1 }; \
                 let r: Point = max(p, q); \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0502"), "expected E0502, got: {codes:?}");
    }

    #[test]
    fn bound_violation_on_impl_block_method_e0502() {
        // v0.0.23: a method from a Copy-bounded impl block (`impl W[T: Copy]`)
        // must reject a non-Copy receiver at the call site. Before this fix,
        // impl-block bounds parsed but were never enforced — only
        // struct-declaration bounds were. (`NC` is non-Copy: it has a `drop`.)
        let codes = errors(
            "struct W[T] { v: T } \
             impl W[T: Copy] { fn dup(this) -> T { return this.v; } } \
             struct NC { x: i32 } \
             impl NC { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let w: W[NC] = W[NC] { v: NC { x: 1 } }; \
                 let _d: NC = w.dup(); \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0502"), "expected E0502, got: {codes:?}");
    }

    #[test]
    fn method_level_generic_bound_on_generic_struct_enforced_e0502() {
        // SOUNDNESS: a method-level generic bound (`fn f[U: Copy]`) on a
        // GENERIC struct was dropped when the struct was instantiated — the
        // synthesized method sig had empty `generic_bounds`, so a non-Copy
        // `U` (a Drop type) was accepted. The body `let a = x; let b = x;`
        // then bit-copies a non-Copy value → double drop. Must be E0502.
        let copy_bound = errors(
            "struct Box[T] { value: T } \
             impl Box[T] { fn dup_arg[U: Copy](this, x: U) -> i32 { let a: U = x; let b: U = x; return 1; } } \
             struct R { tag: i32 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let b: Box[i32] = Box[i32] { value: 0 }; \
                 let r: R = R { tag: 5 }; \
                 return b.dup_arg::[R](r); \
             }",
        );
        assert!(
            copy_bound.contains(&"E0502"),
            "method `U: Copy` bound on generic struct must reject a Drop type, got: {copy_bound:?}"
        );
        // Interface bound is enforced the same way.
        let iface_bound = errors(
            "interface Show { fn show(this) -> i32; } \
             struct Box[T] { value: T } \
             impl Box[T] { fn run[U: Show](this, x: U) -> i32 { return x.show(); } } \
             struct NoShow { n: i32 } \
             fn main() -> i32 { \
                 let b: Box[i32] = Box[i32] { value: 0 }; \
                 let w: NoShow = NoShow { n: 7 }; \
                 return b.run::[NoShow](w); \
             }",
        );
        assert!(
            iface_bound.contains(&"E0502"),
            "method `U: Show` bound on generic struct must reject a non-Show type, got: {iface_bound:?}"
        );
    }

    #[test]
    fn method_level_generic_bound_on_generic_enum_enforced_e0502() {
        // Same soundness fix on the enum instantiation path — both a method
        // and an associated function.
        let method = errors(
            "enum Box[T] { V(T) } \
             impl Box[T] { fn dup[U: Copy](this, x: U) -> i32 { let a: U = x; let b: U = x; return 1; } } \
             struct R { tag: i32 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let b: Box[i32] = Box[i32]::V(0); \
                 let r: R = R { tag: 5 }; \
                 return b.dup::[R](r); \
             }",
        );
        assert!(
            method.contains(&"E0502"),
            "enum method `U: Copy` bound must reject a Drop type, got: {method:?}"
        );
        let assoc = errors(
            "enum Box[T] { V(T) } \
             impl Box[T] { fn mk[U: Copy](x: U) -> i32 { let a: U = x; let b: U = x; return 1; } } \
             struct R { tag: i32 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { let r: R = R { tag: 5 }; return Box[i32]::mk::[R](r); }",
        );
        assert!(
            assoc.contains(&"E0502"),
            "enum assoc-fn `U: Copy` bound must reject a Drop type, got: {assoc:?}"
        );
    }

    #[test]
    fn method_level_generic_bound_on_generic_struct_satisfied_clean() {
        // The bound is checked, not blanket-rejected: a satisfying type
        // (Copy `i32`, or a type that impls the interface) type-checks.
        assert_clean(
            "struct Box[T] { value: T } \
             impl Box[T] { fn dup_arg[U: Copy](this, x: U) -> i32 { let a: U = x; let b: U = x; return 1; } } \
             fn main() -> i32 { \
                 let b: Box[i32] = Box[i32] { value: 0 }; \
                 return b.dup_arg::[i32](5); \
             }",
        );
    }

    #[test]
    fn text_reassign_str_literal_coerces() {
        // TEXT.R1 at the assignment site: `let mut s: Text = "a"; s = "b";`
        // builds — the literal constructs an owned Text, matching the
        // `let`-init coercion. Before the fix this was E0302 (str vs struct).
        assert_clean(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { var s: Text = \"a\"; s = \"b\"; return 0; }",
        );
    }

    #[test]
    fn text_reassign_to_immutable_still_errors_e0305() {
        // The coercion must not paper over immutability: a non-`mut` binding
        // still rejects reassignment (the immutability check fires first).
        let codes = errors(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { let s: Text = \"a\"; s = \"b\"; return 0; }",
        );
        assert!(codes.contains(&"E0305"), "expected E0305, got: {codes:?}");
    }

    #[test]
    fn text_assign_str_value_still_rejected_e0302() {
        // Only a literal coerces; an arbitrary `str` *value* still needs
        // `.to_text()` — assigning one to a Text binding is a type error.
        let codes = errors(
            "#[lang(\"string\")] struct Text { opaque ptr: *u8, len: usize, cap: usize }\n\
             fn main() -> i32 { var s: Text = \"a\"; let v: str = \"b\"; s = v; return 0; }",
        );
        assert!(codes.contains(&"E0302"), "expected E0302, got: {codes:?}");
    }

    #[test]
    fn impl_block_bound_does_not_over_reject_sibling_unbounded_method() {
        // The Copy bound on one impl block must not leak onto a sibling
        // unbounded block: a non-Copy instantiation stays usable through the
        // unbounded methods. Only `dup` requires Copy; `store` does not.
        assert_clean(
            "struct W[T] { v: T } \
             impl W[T] { fn store(ref this, x: T) { this.v = x; return; } } \
             impl W[T: Copy] { fn dup(this) -> T { return this.v; } } \
             struct NC { x: i32 } \
             impl NC { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 var w: W[NC] = W[NC] { v: NC { x: 1 } }; \
                 w.store(NC { x: 2 }); \
                 return 0; \
             }",
        );
    }

    #[test]
    fn generic_fn_infers_type_arg_from_generic_struct_argument() {
        // v0.0.23: `fn get[T](b: Box2[T]) -> T` called as `get(a)` infers T from
        // the concrete `Box2[i32]` argument — no turbofish. Before, the param
        // `Box2[T]` (template id) and the arg `Box2[i32]` (instantiation id)
        // were two distinct `Ty::Struct`s that fell through to `a == b` and
        // failed (E0302), forcing `::[T]` at every generic-over-container call.
        assert_clean(
            "struct Box2[T] { v: T } \
             fn get[T](b: Box2[T]) -> T { return b.v; } \
             fn main() -> i32 { let a: Box2[i32] = Box2[i32] { v: 5 }; let r: i32 = get(a); return r -% 5; }",
        );
    }

    #[test]
    fn generic_struct_inference_still_rejects_mismatched_arg() {
        // The new generic-struct unification must not over-unify: inferring
        // T = bool from a `Box2[bool]` arg, then using the bool result where an
        // i32 is wanted, is still a type error.
        let codes = errors(
            "struct Box2[T] { v: T } \
             fn get[T](b: Box2[T]) -> T { return b.v; } \
             fn main() -> i32 { let a: Box2[bool] = Box2[bool] { v: true }; let r: i32 = get(a); return r; }",
        );
        assert!(codes.contains(&"E0302"), "expected E0302, got: {codes:?}");
    }

    #[test]
    fn match_move_payload_out_of_field_scrutinee_rejected_e0337() {
        // Root fix: `match` on a borrowed-place scrutinee (`h.e`) that moves an
        // owning payload OUT is a partial move — E0337, same as `take(obj.f)`.
        // Before, the match path skipped the move-check and double-freed (the
        // moved payload and the field's owner both dropped it).
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _r: R = match h.e { E::A(x) => x, E::B => R { data: { 0 as *u8 } } }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn match_read_only_payload_of_field_scrutinee_clean() {
        // The fix must reject only the *escaping* move, not a borrow-read: a
        // payload bound from a field scrutinee and only read (passed to a bare
        // read-only param) is sound (the field's owner drops it) and stays accepted.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn rd(r: R) -> i32 { return 0; } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _n: i32 = match h.e { E::A(x) => rd(x), E::B => 0 }; \
                 return 0; \
             }",
        );
    }

    #[test]
    fn match_move_payload_out_of_owned_scrutinee_clean() {
        // The reject is scoped to *projection* scrutinees: moving a payload out
        // of an owned-binding scrutinee (the match consumes the whole value) is
        // fine and must not be over-rejected.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn main() -> i32 { \
                 let e: E = E::A(R { data: { 0 as *u8 } }); \
                 let _r: R = match e { E::A(x) => x, E::B => R { data: { 0 as *u8 } } }; \
                 return 0; \
             }",
        );
    }

    // v0.0.23 root #1: value-transparent wrappers (`{ .. }`, `if`, `match`)
    // peel to their leaf value, so a partial move of a Drop field reached
    // through one is the same E0509 as the bare `obj.f`. Codegen bit-copies all
    // of these into a temp, so without peeling the copy aliased live storage
    // and double-freed. Covers let-init and the match scrutinee.
    #[test]
    fn block_wrapped_field_move_rejected_e0509() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _r: E = { h.e }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0509"), "expected E0509, got: {codes:?}");
    }

    #[test]
    fn match_on_block_wrapped_field_scrutinee_rejected() {
        // The originally-reported repro: `match { h.e } { .. }`. The block makes
        // the scrutinee a value (bit-copied temp), not a place, so the field
        // move is caught at scrutinee evaluation (E0509), not the arm.
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _r: R = match { h.e } { E::A(x) => x, E::B => R { data: { 0 as *u8 } } }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0509"), "expected E0509, got: {codes:?}");
    }

    #[test]
    fn if_wrapped_field_move_rejected_e0509() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _r: E = if { 0 as i32 } == 0 { h.e } else { E::B }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0509"), "expected E0509, got: {codes:?}");
    }

    // v0.0.23 root #2: enum/struct construction *moves* its non-Copy args (codegen
    // disarms the source), so sema must consume a non-Copy whole-binding arg.
    // Without it the binding could be constructed into two aggregates (both
    // bit-copy-alias it → double-free) or read after the move.
    #[test]
    fn enum_construction_consumes_noncopy_arg_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn main() -> i32 { \
                 let y: R = R { data: { 0 as *u8 } }; \
                 let _z1: E = E::A(y); \
                 let _z2: E = E::A(y); \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn struct_construction_consumes_noncopy_arg_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             struct W { r: R } \
             fn main() -> i32 { \
                 let y: R = R { data: { 0 as *u8 } }; \
                 let _w1: W = W { r: y }; \
                 let _w2: W = W { r: y }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn match_arm_reconstructs_payload_from_field_scrutinee_rejected() {
        // `match h.e { E::A(y) => E::A(y) }` rebinds the payload of a *place*
        // scrutinee into a new enum. Now that construction consumes `y`, the
        // payload escapes a borrowed place → E0337 (root #1's arm check fires
        // because root #2 marks `y` moved). Previously double-freed (DROPS=2).
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct H { e: E } \
             fn main() -> i32 { \
                 let h: H = H { e: E::A(R { data: { 0 as *u8 } }) }; \
                 let _r: E = match h.e { E::A(y) => E::A(y), E::B => E::B }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn single_construction_move_of_noncopy_binding_clean() {
        // The consume must not over-reject the legitimate single move: a binding
        // moved into exactly one aggregate, never used again, is sound.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             struct W { r: R } \
             fn main() -> i32 { \
                 let y: R = R { data: { 0 as *u8 } }; \
                 let _z: E = E::A(y); \
                 let y2: R = R { data: { 0 as *u8 } }; \
                 let _w: W = W { r: y2 }; \
                 return 0; \
             }",
        );
    }

    // v0.0.23 unified match ownership model (`classify_scrutinee`) + the
    // raw-deref partial move. The following pin down the model's four-way
    // scrutinee classification and both over- and under-rejection edges.

    #[test]
    fn match_raw_deref_of_drop_type_rejected_e0337() {
        // `match { *p }` for a Drop-carrying pointee bit-copies the value
        // out of a place the deref doesn't own → double-free. Rejected (E0337).
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn main() -> i32 { \
                 let e: E = E::A(R { data: { 0 as *u8 } }); \
                 let p: *E = { #addr_of(e) }; \
                 let _r: R = match { *p } { E::A(x) => x, E::B => R { data: { 0 as *u8 } } }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn let_raw_deref_of_drop_type_rejected_e0337() {
        // The same partial move at a let-init value site (not a match).
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn main() -> i32 { \
                 let e: E = E::A(R { data: { 0 as *u8 } }); \
                 let p: *E = { #addr_of(e) }; \
                 let _x: E = { *p }; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn match_move_out_of_borrow_param_scrutinee_rejected_e0337() {
        // A bare (borrowing) parameter is owned by the caller; matching it and moving a
        // payload out is a partial move of a value owned elsewhere (E0337). This
        // is the `owns_value=false` branch of `classify_scrutinee`.
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn take(e: E) -> i32 { \
                 let _r: R = match e { E::A(x) => x, E::B => R { data: { 0 as *u8 } } }; \
                 return 0; \
             } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn match_read_only_of_borrow_param_scrutinee_clean() {
        // Reading (not moving) a payload of a borrowed-param scrutinee is sound —
        // the payload binding is itself a borrow. Must not be over-rejected.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn rd(r: R) -> i32 { return 0; } \
             fn take(e: E) -> i32 { \
                 let n: i32 = match e { E::A(x) => rd(x), E::B => 1 }; \
                 return n; \
             } \
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn match_copy_field_of_drop_struct_via_deref_clean() {
        // FALSE-POSITIVE GUARD (agent_core::identity repro): reading a *Copy*
        // field (`Option[usize]`-shaped) out of a Drop struct through `(*p).f` is
        // a harmless bit-copy, never a partial move. Must compile.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum Opt { Some(usize), None } \
             struct NodeView { id: R, parent: Opt } \
             fn main() -> i32 { \
                 let nv: NodeView = NodeView { id: R { data: { 0 as *u8 } }, parent: Opt::Some(5 as usize) }; \
                 let p: *NodeView = { #addr_of(nv) }; \
                 let _parent: usize = match { (*p).parent } { Opt::Some(x) => x, Opt::None => 0 as usize }; \
                 return 0; \
             }",
        );
    }

    #[test]
    fn match_raw_deref_of_drop_free_pod_clean() {
        // FALSE-POSITIVE GUARD (agent_core::events repro): copying a non-Copy but
        // *drop-free* value (`{usize, ...}` with no destructor) out of `*p` is
        // harmless — no destructor runs twice — so the gate is `ty_carries_drop`,
        // not `!is_copy`. Must compile.
        assert_clean(
            "struct PodS { a: usize } \
             enum Pod { X(PodS), Y } \
             fn main() -> i32 { \
                 let pd: Pod = Pod::X(PodS { a: 1 as usize }); \
                 let pp: *Pod = { #addr_of(pd) }; \
                 let _out: Pod = match { *pp } { Pod::X(s) => Pod::X(s), Pod::Y => Pod::Y }; \
                 return 0; \
             }",
        );
    }

    // v0.0.23 whole-binding move through value-transparent wrappers: the move
    // *marking* must peel `{}`/`if`/`match` the SAME way partial-move
    // *detection* does, or codegen consumes the binding through the wrapper while
    // sema doesn't → a later use slips through and the value is owned twice
    // (double-free). These pin every consuming site.

    #[test]
    fn let_block_wrapped_move_then_reuse_rejected_e0335() {
        // The reporter's repro: `let y = { x }; let z = x;`.
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _y: R = { x }; \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn let_if_wrapped_move_then_reuse_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _y: R = if { 0 as i32 } == 0 { x } else { R { data: { 0 as *u8 } } }; \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn enum_construct_wrapped_move_then_reuse_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             enum E { A(R), B } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _a: E = E::A({ x }); \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn struct_construct_wrapped_move_then_reuse_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             struct W { r: R } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _w: W = W { r: { x } }; \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn call_arg_wrapped_move_then_reuse_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn sink(take r: R) -> i32 { return 0; } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _n: i32 = sink({ x }); \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn assign_wrapped_move_then_reuse_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 var t: R = R { data: { 0 as *u8 } }; \
                 let x: R = R { data: { 0 as *u8 } }; \
                 t = { x }; \
                 let _z: R = x; \
                 return 0; \
             }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn single_wrapped_move_clean() {
        // The wrapped move itself (no reuse) is sound — `x` moves into `y`.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _y: R = { x }; \
                 return 0; \
             }",
        );
    }

    #[test]
    fn rvalue_arg_to_move_param_clean() {
        // FALSE-POSITIVE GUARD: passing a fresh rvalue to an explicit `take`
        // param is a legitimate ownership transfer — must not be rejected (the
        // old immediate-Ident-only `consume_arg_place` wrongly E0337'd it).
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn mkR() -> R { return R { data: { 0 as *u8 } }; } \
             fn sink(take r: R) -> i32 { return 0; } \
             fn main() -> i32 { let _n: i32 = sink(mkR()); return 0; }",
        );
    }

    // v0.0.23 returned borrows: returning/moving a bare-borrow/`ref` *marker*
    // parameter of a Drop type into an owned value is unsound (it bit-copies a
    // value the caller still owns → double-free; C+ has no copy ctor) → E0337.
    // (The region-typed `borrow A T -> borrow A T` form that once stayed sound
    // is retired in v0.0.24 #9 along with the `borrow` keyword.)

    #[test]
    fn return_borrow_marker_param_rejected_e0337() {
        let codes = errors(
            "struct B { x: i32 } \
             impl B { fn drop(ref this) { return; } } \
             fn steal(r: B) -> B { let out: B = r; return out; } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn return_mut_marker_param_rejected_e0337() {
        let codes = errors(
            "struct B { x: i32 } \
             impl B { fn drop(ref this) { return; } } \
             fn cursor(ref b: B) -> B { return b; } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    // v0.0.23 sibling holes: array and tuple literal elements are moved into the
    // aggregate, so they run the shared consuming-site classifier too — a borrow
    // element is E0337, a Drop-field element is E0509, and a reused binding is a
    // use-after-move (E0335).

    #[test]
    fn array_literal_borrow_element_rejected_e0337() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn f(r: R) -> i32 { let _a: [R; 1] = [r]; return 0; } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn array_literal_reused_binding_rejected_e0335() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn mkR() -> R { return R { data: { 0 as *u8 } }; } \
             fn main() -> i32 { let x: R = mkR(); let _a: [R; 2] = [x, x]; return 0; }",
        );
        assert!(codes.contains(&"E0335"), "expected E0335, got: {codes:?}");
    }

    #[test]
    fn array_literal_drop_field_element_rejected_e0509() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             struct H { r: R } \
             impl H { fn drop(ref this) { return; } } \
             fn mkR() -> R { return R { data: { 0 as *u8 } }; } \
             fn main() -> i32 { let h: H = H { r: mkR() }; let _a: [R; 1] = [h.r]; return 0; }",
        );
        assert!(codes.contains(&"E0509"), "expected E0509, got: {codes:?}");
    }

    #[test]
    fn tuple_literal_borrow_element_rejected_e0337() {
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn f(r: R) -> i32 { let _t: (R, i32) = (r, 0); return 0; } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn array_literal_owned_elements_clean() {
        // Distinct owned values into an array is a legitimate move of each.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } } \
             fn mkR() -> R { return R { data: { 0 as *u8 } }; } \
             fn main() -> i32 { \
                 let p: R = mkR(); let q: R = mkR(); \
                 let _a: [R; 2] = [p, q]; \
                 return 0; \
             }",
        );
    }

    #[test]
    fn move_self_method_on_borrow_param_rejected_e0337() {
        // Laundering path: `r.take()` where `take(take this)` consumes the
        // receiver. Calling it on a bare-borrow param moves the borrow out into an
        // owned value (the caller still drops it) → E0337, same as `return r`.
        let codes = errors(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } fn take(take this) -> R { return this; } } \
             fn steal(r: R) -> R { return r.take(); } \
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0337"), "expected E0337, got: {codes:?}");
    }

    #[test]
    fn move_self_method_on_owned_local_clean() {
        // The same `take this` call on an OWNED local is a legitimate move.
        assert_clean(
            "struct R { opaque data: *u8 } \
             impl R { fn drop(ref this) { return; } fn take(take this) -> R { return this; } } \
             fn main() -> i32 { \
                 let x: R = R { data: { 0 as *u8 } }; \
                 let _y: R = x.take(); \
                 return 0; \
             }",
        );
    }

    #[test]
    fn read_only_borrow_param_reusable_clean() {
        // A bare (borrowing) param read-only and not moved out: the caller keeps it,
        // reusable. Must not be over-rejected by the returned-borrow check.
        assert_clean(
            "struct B { x: i32 } \
             impl B { fn drop(ref this) { return; } } \
             fn rd(b: B) -> i32 { return b.x; } \
             fn main() -> i32 { \
                 let v: B = B { x: 1 }; \
                 let a: i32 = rd(v); \
                 let c: i32 = rd(v); \
                 return a + c; \
             }",
        );
    }

    // v0.0.19: the E0502 message names the *actual* offending type, not the
    // generic `struct` placeholder (the free `ty_display` can't resolve nominal
    // ids; `ty_display_named` does). Helps agents locate the fix.
    #[test]
    fn bound_violation_message_names_the_type_v0019() {
        let diags = check_src(
            "fn max[T: Ord](take a: T, b: T) -> T { return a; } \
             struct Point { x: i32 } \
             fn main() -> i32 { \
                 let p: Point = Point { x: 0 }; \
                 let q: Point = Point { x: 1 }; \
                 let r: Point = max(p, q); \
                 return 0; \
             }",
        );
        let d = diags
            .iter()
            .find(|d| d.code.0 == "E0502")
            .expect("expected E0502");
        assert!(
            d.message.contains("`Point`"),
            "message should name the type `Point`, got: {}",
            d.message
        );
        assert!(
            !d.message.contains("type `struct`"),
            "message should not use the generic `struct` placeholder, got: {}",
            d.message
        );
    }

    // v0.0.19 regression lock: a polymorphic backend built from a user-defined
    // interface bound works end to end — generic fn (inference + turbofish),
    // generic struct field of the bounded type, and a generic impl block that
    // calls the interface method on that field. (Confirms the move-checker /
    // interface-bound-generics "holes" the v0.0.19 plan listed no longer
    // reproduce.)
    #[test]
    fn interface_bound_generic_backend_clean_v0019() {
        assert_clean(
            "interface Backend { fn flush(this) -> i32; } \
             struct Mac { fd: i32 } \
             impl Mac: Backend { fn flush(this) -> i32 { return this.fd; } } \
             struct App[B: Backend] { backend: B } \
             impl App[B: Backend] { fn run(this) -> i32 { return this.backend.flush(); } } \
             fn render[B: Backend](b: B) -> i32 { return b.flush(); } \
             fn main() -> i32 { \
                 let m: Mac = Mac { fd: 3 }; \
                 let viaturbo: i32 = render::[Mac](m); \
                 let a: App[Mac] = App[Mac] { backend: Mac { fd: 4 } }; \
                 return a.run() + viaturbo; \
             }",
        );
    }

    // v0.0.19 `__cplus_*` -> `#` sigil migration: the runtime/atomic builtins are
    // now spelled `#name(...)`.
    // Atomic ops are clean and type as their spec type.
    #[test]
    fn migrated_atomic_intrinsic_in_unsafe_clean_v0019() {
        assert_clean(
            "fn f() -> i32 { \
                 var x: i32 = 0; \
                 let p: *i32 = { #addr_of(x) }; \
                 return { #atomic_load_i32_seqcst(p) }; \
             }",
        );
    }

    // A genuinely-unknown `#name` is still rejected (the migration delegation
    // doesn't swallow non-migrated intrinsic names).
    #[test]
    fn unknown_intrinsic_still_e0905_v0019() {
        let codes = errors("fn f() -> i32 { return #not_a_real_intrinsic(1); }");
        assert!(codes.contains(&"E0905"), "expected E0905, got: {codes:?}");
    }

    // v0.0.19: the legacy bare `__cplus_*(...)` call spelling was removed — only
    // the `#` sigil reaches these builtins. A bare call is an undefined function.
    #[test]
    fn legacy_cplus_call_spelling_rejected_v0019() {
        let codes = errors(
            "fn f() -> i32 { \
                 var x: i32 = 0; \
                 let p: *i32 = { #addr_of(x) }; \
                 return { __cplus_atomic_load_i32_seqcst(p) }; \
             }",
        );
        assert!(codes.contains(&"E0300"), "expected E0300, got: {codes:?}");
    }

    // v0.0.19 regression lock: a Copy struct field passed by value out of
    // `this` is accepted (the move-checker exempts Copy projections). The
    // plan listed an E0337 "even when Copy" hole that no longer reproduces.
    #[test]
    fn copy_struct_field_moved_by_value_out_of_self_clean_v0019() {
        assert_clean(
            "struct Point { x: i32, y: i32 } \
             struct Holder { p: Point, tag: i32 } \
             fn take(p: Point) -> i32 { return p.x; } \
             impl Holder { fn use_field(this) -> i32 { return take(this.p); } } \
             fn main() -> i32 { \
                 let h: Holder = Holder { p: Point { x: 1, y: 2 }, tag: 0 }; \
                 return h.use_field(); \
             }",
        );
    }

