    fn pointer_to_u64_cast_in_unsafe_clean() {
        assert_clean(
            "fn main() -> i32 { \
                let p: *u8 = { 0 as *u8 }; \
                let addr: u64 = { p as u64 }; \
                return 0; \
             }",
        );
    }

