    // v0.0.24: the C-ABI signature check now runs for a PLAIN `export fn` (not
    // just `export extern fn`) — plain exports still get a bare C symbol, so a
    // non-C-representable type in any parameter mode (incl. `take`/`ref`) must be
    // rejected. (Previously the check was gated on `is_extern` and skipped these.)
    #[test]
    fn export_fn_take_drop_type_rejected_e0410() {
        // `take b: Buf` where Buf owns heap + drops: a C caller would pass it by
        // value, C+ would free it, and C's copy would dangle — no safe C mapping.
        let codes = errors(
            "struct Buf { opaque p: *u8 }\n\
             impl Buf { fn drop(ref this) { return; } }\n\
             export fn sink(take b: Buf) -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0410"), "expected E0410, got: {codes:?}");
    }

    #[test]
    fn export_fn_str_param_rejected_e0410() {
        let codes = errors("export fn f(s: str) -> i32 { return 0; }");
        assert!(codes.contains(&"E0410"), "expected E0410, got: {codes:?}");
    }

    #[test]
    fn export_fn_ref_copy_scalar_clean() {
        // `ref n: i32` is a C out-parameter `int*` — C-representable.
        assert_clean("export fn bump(ref n: i32) { n = n +% 1; }");
    }

    #[test]
    fn export_fn_take_copy_clean() {
        // `take` of a Copy type is just by-value — C passes a copy, nothing to free.
        assert_clean("export fn consume(take n: i32) -> i32 { return n; }");
    }

    #[test]
    fn pub_extern_fn_with_unit_return_clean() {
        // Unit return is fine — maps to C `void`.
        assert_clean("export extern fn noop() { return; }");
    }

    #[test]
    fn pub_extern_fn_with_array_clean() {
        // Fixed-size array of C-compatible element is layout-compatible
        // with C `T[N]`.
        assert_clean("export extern fn first(xs: [i32; 4]) -> i32 { return xs[0 as usize]; }");
    }

    #[test]
    fn pub_extern_fn_with_fn_ptr_clean() {
        // Function-pointer params/returns work when their own signatures
        // are C-exportable.
        assert_clean("export extern fn invoke(f: fn(i32) -> i32, x: i32) -> i32 { return f(x); }");
    }

    #[test]
    fn pub_extern_fn_with_fn_ptr_of_slice_rejected_e0410() {
        // A fn-ptr whose param uses a non-C type propagates the rejection.
        let codes = errors("export extern fn bad(f: fn(i32[]) -> i32) -> i32 { return 0; }");
        assert!(codes.contains(&"E0410"), "expected E0410, got: {codes:?}");
    }

    #[test]
    fn pub_extern_fn_with_non_repr_c_field_in_struct_rejected_e0410() {
        // A `#[repr(C)]` struct still must have C-exportable fields.
        let codes = errors(
            "#[repr(C)]\n\
             struct Outer { inner: str }\n\
             export extern fn use_it(o: Outer) -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0410"), "expected E0410, got: {codes:?}");
    }

    // ---- v0.0.3 Phase 5 Slice 5E.2: async fn + await sema ----

    const FUTURE_PRELUDE: &str = "#[lang(\"future\")] struct Future[T] { opaque handle: *u8 } ";

    // R4: a minimal user-defined owned (non-Copy, Drop) struct. Replaces the
    // blessed `string` in tests that just need "some owned heap-ish type" now
    // that the `string` spelling is gone and `Text` is import-required (so it
    // can't appear in a single unvendored snippet).
    const DROP_STRUCT: &str =
        "struct Owned { x: i32 } impl Owned { fn drop(ref this) { return; } } ";

    // R4: a user-defined struct whose `drop` *frees* heap — the freeing-drop
    // signal `#[no_alloc]` (E0901) keys on. Replaces a `string` field, which
    // used to be the convenient freeing-drop type before the spelling's removal.
    const FREEING_DROP: &str = "extern fn free(p: *u8); struct Handle { opaque p: *u8 } impl Handle { fn drop(ref this) { { free(this.p); }; } } ";

    #[test]
    fn async_fn_body_returns_inner_type() {
        // `async fn foo() -> i32` body uses `return X` for X: i32,
        // NOT for X: Future[i32]. The `Future[i32]` wrap is sema's
        // view at call sites only.
        assert_clean(&format!(
            "{FUTURE_PRELUDE}async fn fetch() -> i32 {{ return 42 as i32; }}"
        ));
    }

    #[test]
    fn async_fn_signature_resolves_to_future_at_call_site() {
        // Calling an async fn from a sync context yields `Future[i32]`,
        // which the sync fn can hold but can't await — so we just bind
        // it to a local typed `Future[i32]`.
        assert_clean(&format!(
            "{FUTURE_PRELUDE}async fn fetch() -> i32 {{ return 1 as i32; }} \
             fn main() -> i32 {{ let f: Future[i32] = fetch(); return 0; }}"
        ));
    }

    #[test]
    fn await_outside_async_fn_e0901() {
        let codes = errors(&format!(
            "{FUTURE_PRELUDE}async fn fetch() -> i32 {{ return 1 as i32; }} \
             fn main() -> i32 {{ let x: i32 = await fetch(); return x; }}"
        ));
        assert!(codes.contains(&"E0901"), "expected E0901, got: {codes:?}");
    }

    #[test]
    fn await_of_non_future_e0902() {
        let codes = errors(&format!(
            "{FUTURE_PRELUDE}async fn bad() -> i32 {{ let x: i32 = await (7 as i32); return x; }}"
        ));
        assert!(
            codes.contains(&"E0902"),
            "expected E0902 (await of non-Future), got: {codes:?}"
        );
    }

    #[test]
    fn await_inside_async_fn_yields_inner_type() {
        // Chained async: `outer` awaits `inner`'s Future[i32] and binds
        // the i32 result. Sema-only check; codegen still traps on
        // await but the typecheck must pass.
        assert_clean(&format!(
            "{FUTURE_PRELUDE}async fn inner() -> i32 {{ return 7 as i32; }} \
             async fn outer() -> i32 {{ let x: i32 = await inner(); return x; }}"
        ));
    }

    #[test]
    fn async_fn_without_future_in_scope_e0300() {
        // No Future template imported → wrap_in_future fails.
        let codes = errors("async fn fetch() -> i32 { return 0 as i32; }");
        assert!(
            codes.contains(&"E0300"),
            "expected E0300 (Future not in scope), got: {codes:?}"
        );
    }

    // ---- v0.0.4 Phase 1D: E0900 borrow-across-await parameter guard ----

    #[test]
    fn async_fn_with_str_param_emits_e0900() {
        let codes = errors(&format!(
            "{FUTURE_PRELUDE}async fn fetch(url: str) -> i32 {{ return 0 as i32; }}"
        ));
        assert!(
            codes.contains(&"E0900"),
            "expected E0900 (str borrow in async param), got: {codes:?}"
        );
    }

    #[test]
    fn async_fn_with_slice_param_emits_e0900() {
        let codes = errors(&format!(
            "{FUTURE_PRELUDE}async fn proc(buf: i32[]) -> i32 {{ return 0 as i32; }}"
        ));
        assert!(
            codes.contains(&"E0900"),
            "expected E0900 (slice borrow in async param), got: {codes:?}"
        );
    }

    #[test]
    fn async_fn_with_owned_string_param_clean() {
        // An owned (Drop) struct param is safe to hold across await.
        assert_clean(&format!(
            "{FUTURE_PRELUDE}{DROP_STRUCT}async fn fetch(url: Owned) -> i32 {{ return 0 as i32; }}"
        ));
    }

    #[test]
    fn async_fn_with_copy_param_clean() {
        // i32 is Copy → safe.
        assert_clean(&format!(
            "{FUTURE_PRELUDE}async fn id(x: i32) -> i32 {{ return x; }}"
        ));
    }

    #[test]
    fn async_fn_with_mut_noncopy_param_emits_e0900() {
        // `mut buf: Owned` is pointer-passed in Phase-6 ABI; storage
        // doesn't necessarily live in the coroutine frame.
        let codes = errors(&format!(
            "{FUTURE_PRELUDE}{DROP_STRUCT}async fn proc(ref buf: Owned) -> i32 {{ return 0 as i32; }}"
        ));
        assert!(
            codes.contains(&"E0900"),
            "expected E0900 (mut non-Copy param), got: {codes:?}"
        );
    }

    // ---- v0.0.4 Phase 2 Slice 2A: Send / Sync marker interfaces ----

    #[test]
    fn send_bound_accepts_primitive() {
        // `fn worker[T: Send](take x: T) -> T { return x; }` instantiated with
        // i32 must pass. v0.0.4 baseline is permissive — every type is
        // Send — so this is the canonical "vocabulary works" check.
        assert_clean(
            "fn worker[T: Send](take x: T) -> T { return x; }\n\
             fn main() -> i32 { return worker::[i32](42); }",
        );
    }

    #[test]
    fn send_bound_accepts_user_struct() {
        // User-defined struct: also Send under the v0.0.4 baseline.
        assert_clean(
            "struct Pt { x: i32, y: i32 }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let p: Pt = Pt { x: 1, y: 2 };\n\
                 let q: Pt = ship::[Pt](p);\n\
                 return q.x;\n\
             }",
        );
    }

    #[test]
    fn sync_bound_accepts_primitive() {
        // Same shape, Sync bound.
        assert_clean(
            "fn share[T: Sync](take x: T) -> T { return x; }\n\
             fn main() -> i32 { return share::[i32](42); }",
        );
    }

    #[test]
    fn send_and_sync_compose_with_other_bounds() {
        // Multiple bounds on one type param — verifies the bound-list
        // parsing/resolution sees Send / Sync as first-class.
        assert_clean(
            "fn need_both[T: Send + Sync](take x: T) -> T { return x; }\n\
             fn main() -> i32 { return need_both::[i32](7); }",
        );
    }

    // ---- v0.0.12 realtime Phase 6 (core): Rc / MutexGuard are !Send ----

    #[test]
    fn send_bound_rejects_rc_e0502() {
        // The designated `#[lang("rc")]` type is `!Send` — passing one to a
        // `Send`-bounded generic fails. The marker is what makes it that
        // type; see `a_struct_named_rc_without_the_marker_is_send`.
        let codes = errors(
            "#[lang(\"rc\")]\n\
             struct Rc[T] { v: T }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let r: Rc[i32] = Rc[i32] { v: 5 };\n\
                 let _q: Rc[i32] = ship::[Rc[i32]](r);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn enum_impl_block_copy_bound_enforced_e0502() {
        // The enum receiver path must enforce an `impl Maybe[T: Copy]` block
        // bound at the call site exactly as the struct path does — it shipped
        // without the check, letting `Maybe[NonCopy].get()` bit-copy an owning
        // value (double-free). NC is non-Copy (has drop).
        let codes = errors(
            "enum Maybe[T] { Some(T), None }\n\
             impl Maybe[T: Copy] { fn get(this, d: T) -> T { match this { Maybe::Some(v) => { return v; } Maybe::None => { return d; } } } }\n\
             struct NC { opaque p: *u8 }\n\
             impl NC { fn drop(ref this) { return; } }\n\
             fn f(m: Maybe[NC], d: NC) -> i32 { let _x: NC = m.get(d); return 0; }\n\
             fn main() -> i32 { return 0; }",
        );
        assert!(
            codes.contains(&"E0502"),
            "enum impl-block Copy bound not enforced; got {codes:?}"
        );
    }

    #[test]
    fn enum_impl_block_copy_bound_satisfied_clean() {
        // A Copy type argument satisfies the bound — no error.
        assert_clean(
            "enum Maybe[T] { Some(T), None }\n\
             impl Maybe[T: Copy] { fn get(this, d: T) -> T { match this { Maybe::Some(v) => { return v; } Maybe::None => { return d; } } } }\n\
             fn f(m: Maybe[i32]) -> i32 { return m.get(0); }\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn send_bound_rejects_mutex_guard_e0502() {
        let codes = errors(
            "#[lang(\"mutex_guard\")]\n\
             struct MutexGuard[T] { v: T }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let g: MutexGuard[i32] = MutexGuard[i32] { v: 5 };\n\
                 let _q: MutexGuard[i32] = ship::[MutexGuard[i32]](g);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn sync_bound_rejects_rc_e0502() {
        let codes = errors(
            "#[lang(\"rc\")]\n\
             struct Rc[T] { v: T }\n\
             fn share[T: Sync](take x: T) -> T { return x; }\n\
             fn main() -> i32 {\n\
                 let r: Rc[i32] = Rc[i32] { v: 5 };\n\
                 let _q: Rc[i32] = share::[Rc[i32]](r);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn unmarked_runtime_abi_prefix_rejected_e0919() {
        // issue-06 step 6: `__cplus_` names symbols the compiler generates.
        // Claiming one without saying so could displace it at link time.
        let codes = errors(
            "extern fn __cplus_reactor_get_state() -> *u8;\n\
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0919"), "got {:?}", codes);
    }

    #[test]
    fn marked_runtime_abi_declaration_is_accepted() {
        // The stdlib's reactor bindings are the legitimate case: they DO name
        // compiler-generated symbols, and now they say so.
        assert_clean(
            "#[runtime_abi]\n\
             extern fn __cplus_reactor_get_state() -> *u8;\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn a_struct_named_rc_without_the_marker_is_send() {
        // issue-06 step 4: the `!Send` rule keys on the designated identity,
        // not on the name. A package that happens to call its own type `Rc`
        // gets no unsendability from the coincidence.
        assert_clean(
            "struct Rc[T] { v: T }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let r: Rc[i32] = Rc[i32] { v: 5 };\n\
                 let _q: Rc[i32] = ship::[Rc[i32]](r);\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn send_bound_accepts_other_generic_struct() {
        // A generic struct that is *not* Rc/MutexGuard stays Send.
        assert_clean(
            "struct Holder[T] { v: T }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let h: Holder[i32] = Holder[i32] { v: 5 };\n\
                 let q: Holder[i32] = ship::[Holder[i32]](h);\n\
                 return q.v;\n\
             }",
        );
    }

    #[test]
    fn mutex_guard_is_still_sync() {
        // Only Rc is !Sync; a MutexGuard satisfies a Sync bound.
        assert_clean(
            "struct MutexGuard[T] { v: T }\n\
             fn share[T: Sync](take x: T) -> T { return x; }\n\
             fn main() -> i32 {\n\
                 let g: MutexGuard[i32] = MutexGuard[i32] { v: 5 };\n\
                 let q: MutexGuard[i32] = share::[MutexGuard[i32]](g);\n\
                 return q.v;\n\
             }",
        );
    }

    // ---- v0.0.14: broad raw-pointer !Send rule + `impl T: Send/Sync {}` ----

    #[test]
    fn send_rejects_raw_ptr_struct_e0502() {
        // A struct that hides a raw pointer is !Send by the structural rule.
        let codes = errors(
            "struct Handle { opaque p: *u8 }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let h: Handle = Handle { p: { 0 as *u8 } };\n\
                 let _q: Handle = ship::[Handle](h);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn sync_rejects_raw_ptr_struct_e0502() {
        let codes = errors(
            "struct Handle { opaque p: *u8 }\n\
             fn share[T: Sync](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let h: Handle = Handle { p: { 0 as *u8 } };\n\
                 let _q: Handle = share::[Handle](h);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn unsafe_impl_send_overrides_raw_ptr_struct() {
        // `impl Handle: Send {}` re-enables the marker.
        assert_clean(
            "struct Handle { opaque p: *u8 }\n\
             impl Handle: Send {}\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let h: Handle = Handle { p: { 0 as *u8 } };\n\
                 let _q: Handle = ship::[Handle](h);\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn bare_raw_pointer_stays_send() {
        // A *bare* raw pointer (not wrapped in a nominal type) is still Send —
        // every use is a visibly raw operation (self-flagging by syntax); the
        // rule targets pointer-hiding structs. Preserves `thread::spawn::[*u8]`.
        assert_clean(
            "fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let p: *u8 = { 0 as *u8 };\n\
                 let _q: *u8 = ship::[*u8](p);\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn unsafe_impl_send_conditional_generic_met() {
        // `impl Arc[T: Send + Sync]: Send` — Arc[i32] is Send
        // because i32 is Send + Sync.
        assert_clean(
            "struct Arc[T] { opaque ctrl: *u8 }\n\
             impl Arc[T: Send + Sync]: Send {}\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let a: Arc[i32] = Arc[i32] { ctrl: { 0 as *u8 } };\n\
                 let _q: Arc[i32] = ship::[Arc[i32]](a);\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn unsafe_impl_send_conditional_generic_unmet_e0502() {
        // Arc[Handle] is !Send: the conditional bound `T: Send` is unmet
        // because Handle (raw-ptr struct, no override) is itself !Send.
        let codes = errors(
            "struct Handle { opaque p: *u8 }\n\
             struct Arc[T] { opaque ctrl: *u8 }\n\
             impl Arc[T: Send + Sync]: Send {}\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let a: Arc[Handle] = Arc[Handle] { ctrl: { 0 as *u8 } };\n\
                 let _q: Arc[Handle] = ship::[Arc[Handle]](a);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    #[test]
    fn struct_holding_overridden_send_field_is_send() {
        // A struct whose only pointer is reached *through* a Send-overridden
        // sub-type is itself Send (the recursion stops at the override).
        assert_clean(
            "struct Arc[T] { opaque ctrl: *u8 }\n\
             impl Arc[T: Send + Sync]: Send {}\n\
             struct Wrap { inner: Arc[i32], tag: i32 }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let w: Wrap = Wrap { inner: Arc[i32] { ctrl: { 0 as *u8 } }, tag: 1 };\n\
                 let _q: Wrap = ship::[Wrap](w);\n\
                 return 0;\n\
             }",
        );
    }

    #[test]
    fn bare_impl_send_registers_marker_override() {
        assert_clean(
            "struct Handle { opaque p: *u8 }\n\
             impl Handle: Send {}\n\
             fn main() -> i32 { return 0; }",
        );
    }

    #[test]
    fn double_underscore_item_names_reserved_e0917() {
        // `__` is the monomorphization arg-joiner (`Box[i32]` → `Box__i32`);
        // a user item squatting on the sequence collides with instantiation
        // symbols (non-injective mangling). Reserved like C reserves `__`.
        for src in [
            "struct Box__i32 { v: i32 }\nfn main() -> i32 { return 0; }",
            "enum Maybe__T { A, B }\nfn main() -> i32 { return 0; }",
            "fn h__i32() -> i32 { return 0; }\nfn main() -> i32 { return h__i32(); }",
        ] {
            let codes = errors(src);
            assert!(
                codes.contains(&"E0917"),
                "expected E0917 for reserved `__` name, got {codes:?} in: {src}"
            );
        }
    }

    #[test]
    fn boundary_double_underscore_names_allowed_not_e0917() {
        // A `__` run only at a boundary can't be a `<template>__<args>` mangling
        // (one side is empty), so it must NOT fire E0917. Trailing `__` is the
        // Fortran/LAPACK C-symbol convention (`chla_transtype__`, in
        // vendor/accelerate/clapack) bound 1:1 via a wrapper fn.
        assert_clean(
            "fn chla_transtype__() -> i32 { return 0; } \
             fn main() -> i32 { return chla_transtype__(); }",
        );
    }

    #[test]
    fn reassign_through_self_consuming_method_reinitializes() {
        // Root of the iris @ui builder-vs-mutator bug: `n = n.consume()` — a
        // take-self method returning the same type — must RE-INITIALIZE `n`, not
        // leave it moved. The move happens in the RHS, so the target's moved flag
        // has to clear AFTER the value is checked. Pre-fix the trailing `.bump()`
        // was E0335 "use of moved value `n`".
        assert_clean(
            "struct N { x: i32 } \
             impl N { \
                 fn drop(ref this) { return; } \
                 fn wider(take this, v: i32) -> N { var m: N = this; m.x = v; return m; } \
                 fn bump(ref this) { this.x = this.x + 1; } \
             } \
             fn main() -> i32 { \
                 var n: N = N { x: 0 }; \
                 n.bump(); \
                 n = n.wider(3); \
                 n.bump(); \
                 return n.x; \
             }",
        );
    }

    #[test]
    fn double_underscore_allowed_in_extern_and_single_underscore_names() {
        // Extern fns bind existing C symbols (`__errno_location`) and never
        // monomorphize; ordinary single underscores stay legal everywhere;
        // LEADING double underscores are implementation-owned and mangle-
        // safe (an instantiation's template base is never empty) — the
        // doctest harness synthesizes `__doctest_helper_N` fns.
        assert_clean(
            "extern fn __errno_location() -> *i32;\n\
             struct my_box { v: i32 }\n\
             fn make_box() -> my_box { return my_box { v: 1 }; }\n\
             fn __doctest_helper_0() { return; }\n\
             fn main() -> i32 { __doctest_helper_0(); return make_box().v; }",
        );
    }

    #[test]
    fn nonempty_send_marker_impl_rejected_e0915() {
        // `Send`/`Sync` are marker interfaces: the assertion is the empty
        // body itself. Methods in the body are rejected.
        let codes = errors(
            "struct Handle { opaque p: *u8 }\n\
             impl Handle { fn drop(ref this) { return; } }\n\
             impl Handle: Send { fn x(this) -> i32 { return 0; } }\n\
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0915"), "got {:?}", codes);
    }

    #[test]
    fn empty_impl_on_regular_interface_rejected_e0916() {
        let codes = errors(
            "interface Greet { fn hi(this) -> i32; }\n\
             struct S { x: i32 }\n\
             impl S: Greet {}\n\
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0916"), "got {:?}", codes);
    }

    #[test]
    fn enum_with_raw_ptr_payload_is_not_send_e0502() {
        // The rule reaches through enum payloads too.
        let codes = errors(
            "enum Maybe { None, Ptr(*u8) }\n\
             fn ship[T: Send](take v: T) -> T { return v; }\n\
             fn main() -> i32 {\n\
                 let m: Maybe = Maybe::None;\n\
                 let _q: Maybe = ship::[Maybe](m);\n\
                 return 0;\n\
             }",
        );
        assert!(codes.contains(&"E0502"), "got {:?}", codes);
    }

    // ---- v0.0.6 Slice 1A: include_bytes! ----

    /// Helper: write `src` to `<dir>/src.cplus`, write `bytes` to
    /// `<dir>/<asset_name>`, and run sema against the source file using
    /// the temp source's path so relative include_bytes! paths resolve.
    fn check_with_asset(src: &str, asset_name: &str, bytes: &[u8]) -> Vec<Diagnostic> {
        let dir = tempfile::tempdir().expect("tempdir");
        let src_path = dir.path().join("src.cplus");
        let asset_path = dir.path().join(asset_name);
        std::fs::write(&src_path, src).expect("write src");
        std::fs::write(&asset_path, bytes).expect("write asset");
        let toks = tokenize(src).expect("lex");
        let prog = parse(toks).expect("parse");
        let diags = check(&prog, src_path, src);
        drop(dir);
        diags
    }

    #[test]
    fn include_bytes_clean_when_file_exists() {
        let diags = check_with_asset(
            "fn main() -> i32 { let p = #include_bytes(\"hello.bin\"); return 0; }",
            "hello.bin",
            b"hello",
        );
        assert!(diags.is_empty(), "expected clean, got: {:#?}", diags);
    }

    /// Project-mode sema over `<dir>/src/main.cplus` with a `Cplus.toml` at
    /// `<dir>` — so the include/shader package boundary (E0918) is active.
    /// Returns the error codes.
    fn check_project_src(src: &str, extra_files: &[(&str, &[u8])]) -> Vec<&'static str> {
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("Cplus.toml"), "[package]\nname=\"p\"").expect("toml");
        std::fs::create_dir_all(dir.path().join("src")).expect("mkdir src");
        for (rel, bytes) in extra_files {
            let p = dir.path().join(rel);
            std::fs::create_dir_all(p.parent().unwrap()).expect("mkdir asset parent");
            std::fs::write(&p, bytes).expect("write asset");
        }
        let src_path = dir.path().join("src/main.cplus");
        std::fs::write(&src_path, src).expect("write src");
        let toks = tokenize(src).expect("lex");
        let prog = parse(toks).expect("parse");
        let diags = check(&prog, src_path, src);
        let codes: Vec<&'static str> = diags
            .iter()
            .filter(|d| matches!(d.severity, Severity::Error))
            .map(|d| Box::leak(d.code.0.to_string().into_boxed_str()) as &str)
            .collect();
        drop(dir);
        codes
    }

    #[test]
    fn include_bytes_escaping_package_is_rejected_e0918() {
        // Absolute path and a `..`-chain that leaves the package must both be
        // rejected in project mode — untrusted source can't embed an arbitrary
        // readable host file.
        for bad in ["/etc/hosts", "../../../../etc/hosts"] {
            let src = format!(
                "fn main() -> i32 {{ let p = #include_bytes(\"{bad}\"); return 0; }}"
            );
            let codes = check_project_src(&src, &[]);
            assert!(
                codes.contains(&"E0918"),
                "expected E0918 for `{bad}`, got {codes:?}"
            );
        }
    }

    #[test]
    fn include_str_escaping_package_is_rejected_e0918() {
        let codes = check_project_src(
            "fn main() -> i32 { let s = #include_str(\"../../../../etc/hosts\"); return 0; }",
            &[],
        );
        assert!(codes.contains(&"E0918"), "got {codes:?}");
    }

    #[test]
    fn include_bytes_in_package_sibling_dir_is_allowed() {
        // The android_view shape: `../adapter/asset.bin` from `src/` stays
        // inside the package, so it must resolve and read cleanly (no E0918,
        // no E0870).
        let codes = check_project_src(
            "fn main() -> i32 { let p = #include_bytes(\"../adapter/asset.bin\"); return 0; }",
            &[("adapter/asset.bin", b"payload")],
        );
        assert!(
            !codes.contains(&"E0918") && !codes.contains(&"E0870"),
            "in-package `../` include must be allowed, got {codes:?}"
        );
    }

    #[test]
    fn include_path_escapes_package_unit() {
        // Direct unit coverage of the boundary helper independent of sema.
        let dir = tempfile::tempdir().expect("tempdir");
        std::fs::write(dir.path().join("Cplus.toml"), "x").expect("toml");
        std::fs::create_dir_all(dir.path().join("src")).expect("src");
        let base = dir.path().join("src");
        // In-package: bare, nested, and in-package `..` all stay contained.
        assert!(!include_path_escapes_package(&base, "asset.bin"));
        assert!(!include_path_escapes_package(&base, "sub/asset.bin"));
        assert!(!include_path_escapes_package(&base, "../adapter/asset.bin"));
        // Escapes: absolute and a `..` chain leaving the package.
        assert!(include_path_escapes_package(&base, "/etc/passwd"));
        assert!(include_path_escapes_package(&base, "../../../../etc/passwd"));
        // No Cplus.toml ancestor → single-file mode → no boundary (allow),
        // matching the import posture.
        let loose = tempfile::tempdir().expect("tempdir2");
        assert!(!include_path_escapes_package(loose.path(), "/etc/passwd"));
    }

    #[test]
    fn include_bytes_missing_file_e0870() {
        // Reference a sibling file that does not exist.
        let dir = tempfile::tempdir().expect("tempdir");
        let src_path = dir.path().join("src.cplus");
        let src = "fn main() -> i32 { let p = #include_bytes(\"missing.bin\"); return 0; }";
        std::fs::write(&src_path, src).expect("write");
        let toks = tokenize(src).expect("lex");
        let prog = parse(toks).expect("parse");
        let diags = check(&prog, src_path, src);
        let codes: Vec<_> = diags
            .iter()
            .filter(|d| matches!(d.severity, Severity::Error))
            .map(|d| d.code.0)
            .collect();
        assert!(codes.contains(&"E0870"), "expected E0870, got {:?}", codes);
    }

    #[test]
    fn include_bytes_non_literal_arg_parse_error() {
        // The parser only constructs ExprKind::IncludeBytes for the
        // strict `include_bytes!(StringLit)` form. A bare identifier
        // fails parse before sema sees it.
        let src = "fn main() -> i32 { let p = include_bytes!(some_var); return 0; }";
        let toks = tokenize(src).expect("lex");
        assert!(
            parse(toks).is_err(),
            "expected parse error on non-literal include_bytes! arg"
        );
    }

    #[test]
    fn include_bytes_type_is_rawptr_to_byte_array() {
        // Round-trip: assigning the result to a `*[u8; N]` typed local
        // succeeds; assigning to a wrong N is a type mismatch.
        let dir = tempfile::tempdir().expect("tempdir");
        let src_path = dir.path().join("src.cplus");
        let asset_path = dir.path().join("bytes.bin");
        std::fs::write(&src_path, "").expect("write");
        std::fs::write(&asset_path, b"abc").expect("write"); // len 3
        let src = "fn main() -> i32 { let p: *[u8; 3] = #include_bytes(\"bytes.bin\"); return 0; }";
        std::fs::write(&src_path, src).expect("write");
        let toks = tokenize(src).expect("lex");
        let prog = parse(toks).expect("parse");
        let diags = check(&prog, src_path, src);
        assert!(
            !diags.iter().any(|d| matches!(d.severity, Severity::Error)),
            "expected clean assignment to *[u8; 3], got: {:#?}",
            diags
        );
    }

    #[test]
    fn include_bytes_wrong_length_type_mismatch() {
        let dir = tempfile::tempdir().expect("tempdir");
        let src_path = dir.path().join("src.cplus");
        let asset_path = dir.path().join("bytes.bin");
        std::fs::write(&asset_path, b"abc").expect("write"); // len 3
        let src = "fn main() -> i32 { let p: *[u8; 5] = #include_bytes(\"bytes.bin\"); return 0; }";
        std::fs::write(&src_path, src).expect("write");
        let toks = tokenize(src).expect("lex");
        let prog = parse(toks).expect("parse");
        let diags = check(&prog, src_path, src);
        assert!(
            diags.iter().any(|d| matches!(d.severity, Severity::Error)),
            "expected a type-mismatch diagnostic for [u8; 5] vs [u8; 3]"
        );
    }

    // ---- v0.0.7 Slice 2.1: SIMD shuffles + reductions + masked ops ----

    #[test]
    fn simd_compare_returns_mask_clean() {
        // `f32x4.lt(b)` produces a mask32x4 (signed-int SIMD of
        // matching width). Sema accepts assigning the result to a
        // mask32x4 binding.
        assert_clean(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let b: f32x4 = f32x4::splat(2.0f32); \
                let m: mask32x4 = a.lt(b); \
                let _r: i32 = m.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_select_on_mask_clean() {
        assert_clean(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let b: f32x4 = f32x4::splat(2.0f32); \
                let m: mask32x4 = a.lt(b); \
                let blended: f32x4 = m.select(a, b); \
                let _r: f32 = blended.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_any_all_on_mask_clean() {
        assert_clean(
            "fn main() -> i32 { \
                let a: i32x4 = i32x4::splat(5); \
                let m: mask32x4 = a.gt(i32x4::splat(0)); \
                let h: bool = m.any(); \
                let q: bool = m.all(); \
                if h { if q { return 0; } } \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_reductions_return_lane_scalar() {
        assert_clean(
            "fn main() -> i32 { \
                let v: f32x4 = f32x4::splat(1.0f32); \
                let s: f32 = v.sum(); \
                let p: f32 = v.product(); \
                let lo: f32 = v.min_across(); \
                let hi: f32 = v.max_across(); \
                if s != 0.0f32 { return 1; } \
                if p != 0.0f32 { return 2; } \
                if lo != 0.0f32 { return 3; } \
                if hi != 0.0f32 { return 4; } \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_reverse_clean() {
        assert_clean(
            "fn main() -> i32 { \
                let v: f32x4 = f32x4::splat(1.0f32); \
                let r: f32x4 = v.reverse(); \
                let _x: f32 = r.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_swizzle_clean() {
        // Swizzle accepts a `[u32; N]` array literal.
        assert_clean(
            "fn main() -> i32 { \
                let v: f32x4 = f32x4::new(1.0f32, 2.0f32, 3.0f32, 4.0f32); \
                let s: f32x4 = v.swizzle([3 as u32, 2 as u32, 1 as u32, 0 as u32]); \
                let _y: f32 = s.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_interleave_clean() {
        assert_clean(
            "fn main() -> i32 { \
                let a: i32x4 = i32x4::splat(1); \
                let b: i32x4 = i32x4::splat(2); \
                let lo: i32x4 = a.interleave_lo(b); \
                let hi: i32x4 = a.interleave_hi(b); \
                let _l: i32 = lo.lane(0 as u32); \
                let _h: i32 = hi.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    // ---- v0.0.9 follow-up: Ty::Mask distinct from Ty::Simd ----

    #[test]
    fn simd_mask_no_implicit_coerce_from_simd_e0302() {
        // Pre-v0.0.9, mask32x4 was a type alias for i32x4 — assigning a
        // splat'd i32x4 to a mask binding worked silently. With Ty::Mask
        // distinct, the assignment is a real type mismatch.
        assert_only_code(
            "fn main() -> i32 { \
                let v: i32x4 = i32x4::splat(0); \
                let m: mask32x4 = v; \
                return 0; \
            }",
            "E0302",
        );
    }

    #[test]
    fn simd_mask_no_implicit_coerce_to_simd_e0302() {
        // The reverse direction: a mask value can't silently become an
        // integer SIMD. Caller must use `.to_bits()` explicitly.
        assert_only_code(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let m: mask32x4 = a.lt(a); \
                let v: i32x4 = m; \
                return 0; \
            }",
            "E0302",
        );
    }

    #[test]
    fn simd_mask_arithmetic_rejected_e0324() {
        // Masks have no arithmetic — they're 0/all-ones bitmasks; `+`
        // would break the invariant. Caller must convert via `.to_bits()`
        // if they really want lane-wise arithmetic on the underlying ints.
        assert_only_code(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let m1: mask32x4 = a.lt(a); \
                let m2: mask32x4 = a.gt(a); \
                let _r: mask32x4 = m1.add(m2); \
                return 0; \
            }",
            "E0324",
        );
    }

    #[test]
    fn simd_mask_to_bits_clean() {
        // `.to_bits()` is the explicit Mask → Simd conversion (zero-cost
        // at the IR level; just relabels the type). Returns the signed-
        // int SIMD of matching lane width.
        assert_clean(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let m: mask32x4 = a.lt(a); \
                let bits: i32x4 = m.to_bits(); \
                let _r: i32 = bits.lane(0 as u32); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_simd_to_mask_clean() {
        // `.to_mask()` is the reverse — Simd → Mask. Only valid on
        // signed-int SIMD (the lane sign convention disambiguates).
        assert_clean(
            "fn main() -> i32 { \
                let v: i32x4 = i32x4::splat(0); \
                let m: mask32x4 = v.to_mask(); \
                let _b: bool = m.any(); \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_unsigned_to_mask_rejected_e0324() {
        // `to_mask` rejects unsigned-int SIMD — there's no `umaskNxM`
        // type and the lane-sign convention picks the signed form.
        assert_only_code(
            "fn main() -> i32 { \
                let v: u32x4 = u32x4::splat(0); \
                let m: mask32x4 = v.to_mask(); \
                return 0; \
            }",
            "E0324",
        );
    }

    #[test]
    fn simd_mask_bitwise_combine_clean() {
        // `.and` / `.or` / `.xor` / `.not` work on Mask receivers
        // (mask combining is a primary use case) and return Mask.
        assert_clean(
            "fn main() -> i32 { \
                let a: f32x4 = f32x4::splat(1.0f32); \
                let m1: mask32x4 = a.lt(a); \
                let m2: mask32x4 = a.gt(a); \
                let both: mask32x4 = m1.and(m2); \
                let either: mask32x4 = m1.or(m2); \
                let neither: mask32x4 = both.not(); \
                if neither.any() { return 0; } \
                return 0; \
            }",
        );
    }

    #[test]
    fn simd_to_bits_on_simd_rejected_e0324() {
        // `to_bits` is mask-only; calling on a Simd is a misuse (the
        // value IS already an integer SIMD).
        assert_only_code(
            "fn main() -> i32 { \
                let v: i32x4 = i32x4::splat(0); \
                let _r: i32x4 = v.to_bits(); \
                return 0; \
            }",
            "E0324",
        );
    }

    #[test]
    fn simd_select_on_non_mask_e0324() {
        // `.select` on a float SIMD (not a mask) must reject.
        let codes = errors(
            "fn main() -> i32 { \
                let v: f32x4 = f32x4::splat(1.0f32); \
                let r: f32x4 = v.select(v, v); \
                if r.lane(0 as u32) != 0.0f32 { return 1; } \
                return 0; \
            }",
        );
        assert!(codes.contains(&"E0324"), "expected E0324, got {:?}", codes);
    }

