    #[test]
    fn no_block_calls_unmarked_user_fn_e0907() {
        let codes = errors(
            "fn helper(x: i32) -> i32 { return x +% 1; }\n\
             #[no_block] fn caller(x: i32) -> i32 { return helper(x); }\n\
             fn main() -> i32 { return 0; }",
        );
        assert!(codes.contains(&"E0907"), "got {:?}", codes);
    }

